const MODULE_PREFIX: Record<string, string> = { dashboard: 'DSH', planning: 'PLN', investments: 'INV', retirement: 'APT', 'children-education': 'EDU', 'investor-profile': 'PER', wellness: 'WEL', 'credit-score': 'CRD', debts: 'DIV', assets: 'PAT', tax: 'TRB', reports: 'REL', transactions: 'FIN', cards: 'CAR', recurrences: 'REC', family: 'FAM', settings: 'CFG' };
const SCREEN_CODE_OVERRIDE: Record<Route, string> = { dashboard: 'DSH001', transactions: 'FIN001', accounts: 'FIN002', categories: 'CAD003', 'dashboard/cash-flow': 'FIN010', 'planning/budget': 'PLN001', 'planning/goals': 'PLN002', 'planning/emergency-fund': 'PLN003' };
const SCREEN_REGISTRY: ScreenDefinition[] = MENU_GROUPS.flatMap((group) => group.items.map((item, index) => ({ ...item, code: SCREEN_CODE_OVERRIDE[item.route] ?? `${MODULE_PREFIX[group.id]}${String(index + 101).padStart(3, '0')}`, module: group.label, icon: group.icon, description: `${item.label} — ${group.label}`, permission: `${group.id}.${item.route.split('/').at(-1)}.visualizar`, singleton: true })));
const WORKSPACE_STORAGE_KEY = 'familyplus-workspace-v1';
function screenForRoute(route: Route) { return SCREEN_REGISTRY.find((screen) => screen.route === route) ?? SCREEN_REGISTRY[0]; }
function safeWorkspaceState(activeRoute: Route): WorkspaceState {
  try {
    const stored = JSON.parse(window.localStorage.getItem(WORKSPACE_STORAGE_KEY) ?? '{}') as Partial<WorkspaceState>;
    const validRoutes = new Set(SCREEN_REGISTRY.map((screen) => screen.route));
    const openRoutes = [...new Set((stored.openRoutes ?? []).filter((route) => validRoutes.has(route)))];
    const favorites = [...new Set((stored.favorites ?? []).filter((route) => validRoutes.has(route)))];
    const recentRoutes = [...new Set((stored.recentRoutes ?? []).filter((route) => validRoutes.has(route)))].slice(0, 10);
    const restoredActive = stored.activeRoute && validRoutes.has(stored.activeRoute) ? stored.activeRoute : activeRoute;
    return { openRoutes: ['dashboard', ...openRoutes.filter((route) => route !== 'dashboard')], activeRoute: restoredActive, favorites, recentRoutes };
  } catch { return { openRoutes: ['dashboard'], activeRoute, favorites: [], recentRoutes: [] }; }
}

function money(cents: number) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(cents / 100); }
function date(value: string) { return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium' }).format(new Date(value)); }
function routeFromHash(): Route { const value = window.location.hash.replace('#/', ''); return MENU_GROUPS.some((group) => group.items.some((item) => item.route === value)) ? value : safeWorkspaceState('dashboard').activeRoute; }

function App() {
  const [configured, setConfigured] = useState<boolean | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [route, setRoute] = useState<Route>(routeFromHash());
  const [toast, setToast] = useState<Toast>(null);

  const notify = (message: string, kind: ToastKind = 'success') => { setToast({ message, kind }); window.setTimeout(() => setToast(null), 4200); };
  const changeRoute = (next: Route) => { window.location.hash = `/${next}`; setRoute(next); };

  useEffect(() => {
    const init = async () => {
      try {
        const status = await api.setupStatus();
        setConfigured(status.configured);
        if (status.configured) {
          try { setUser(await api.me()); } catch { setSession(''); }
        }
      } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível conectar à API.', 'error'); setConfigured(false); }
    };
    void init();
    const listener = () => setRoute(routeFromHash());
    window.addEventListener('hashchange', listener);
    return () => window.removeEventListener('hashchange', listener);
  }, []);

  if (configured === null) return <div className="loading-screen">Preparando o Family+ local…</div>;
  if (!configured || !user) return <AccessScreen configured={configured} onAuthenticated={(auth) => { setSession(auth.token); setUser({ id: auth.usuarioId, nome: auth.nome, login: '' }); setConfigured(true); notify('Acesso local liberado.'); }} notify={notify} />;

  return <Shell user={user} route={route} setRoute={changeRoute} onLogout={async () => { try { await api.logout(); } finally { setSession(''); setUser(null); notify('Sessão encerrada.'); } }} toast={toast} notify={notify} />;
}

function AccessScreen({ configured, onAuthenticated, notify }: { configured: boolean; onAuthenticated: (auth: { usuarioId: string; nome: string; token: string }) => void; notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [nome, setNome] = useState(''); const [login, setLogin] = useState(''); const [senha, setSenha] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true);
    try { const result = configured ? await api.login({ login, senha }) : await api.setup({ nome, login, senha }); onAuthenticated(result); }
    catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível entrar.', 'error'); }
    finally { setBusy(false); }
  };
  return <main className="access-layout"><section className="brand-panel"><div className="brand-mark">F+</div><p className="eyebrow">SISTEMA FINANCEIRO LOCAL</p><h1>Seus dados ficam na sua máquina.</h1><p>Controle familiar privado, sem conta online e sem depender de internet para operar.</p><div className="offline-pill">● Modo local e offline</div></section><section className="access-card"><p className="eyebrow">{configured ? 'BEM-VINDO DE VOLTA' : 'PRIMEIRO ACESSO'}</p><h2>{configured ? 'Entre no Family+' : 'Crie o administrador local'}</h2><p>{configured ? 'Use o acesso configurado neste dispositivo.' : 'Esse perfil controla o espaço financeiro desta instalação.'}</p><Form onSubmit={submit}>{!configured && <Field label="Seu nome"><input value={nome} onChange={(event) => setNome(event.target.value)} placeholder="Ex.: Pablo" autoComplete="name" /></Field>}<Field label="Login"><input value={login} onChange={(event) => setLogin(event.target.value)} placeholder="Ex.: pablo" autoComplete="username" /></Field><Field label="Senha local"><input value={senha} onChange={(event) => setSenha(event.target.value)} type="password" minLength={8} placeholder="No mínimo 8 caracteres" autoComplete={configured ? 'current-password' : 'new-password'} /></Field><Button type="submit" disabled={busy}>{busy ? 'Processando…' : configured ? 'Entrar' : 'Criar acesso local'}</Button></Form></section></main>;
}

function Shell({ user, route, setRoute, onLogout, toast, notify }: { user: User; route: Route; setRoute: (route: Route) => void; onLogout: () => void; toast: Toast; notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [filter, setFilter] = useState('');
  const [openGroups, setOpenGroups] = useState<string[]>(['dashboard', 'transactions', 'cards', 'family', 'settings']);
  const [workspace, setWorkspace] = useState<WorkspaceState>(() => safeWorkspaceState(route));
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [paletteQuery, setPaletteQuery] = useState('');
  const [closePrompt, setClosePrompt] = useState<Route | null>(null);
  const activeGroup = MENU_GROUPS.find((group) => group.items.some((item) => item.route === route));
  const normalizedFilter = filter.trim().toLocaleLowerCase('pt-BR');
  const visibleGroups = MENU_GROUPS.map((group) => ({ ...group, items: normalizedFilter ? group.items.filter((item) => `${group.label} ${item.label}`.toLocaleLowerCase('pt-BR').includes(normalizedFilter)) : group.items })).filter((group) => group.items.length > 0);
  const isOpen = (id: string) => Boolean(normalizedFilter) || openGroups.includes(id) || activeGroup?.id === id;
  const toggleGroup = (id: string) => setOpenGroups((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id]);
  const openScreen = (nextRoute: Route) => {
    const screen = screenForRoute(nextRoute);
    setWorkspace((current) => ({ ...current, openRoutes: current.openRoutes.includes(screen.route) ? current.openRoutes : [...current.openRoutes, screen.route], activeRoute: screen.route, recentRoutes: [screen.route, ...current.recentRoutes.filter((item) => item !== screen.route)].slice(0, 10) }));
    setRoute(screen.route);
  };
  const closeScreen = (targetRoute: Route) => {
    if (targetRoute === 'dashboard') return;
    setWorkspace((current) => {
      const remaining = current.openRoutes.filter((item) => item !== targetRoute);
      const activeRoute = current.activeRoute === targetRoute ? remaining.at(-1) ?? 'dashboard' : current.activeRoute;
      if (activeRoute !== route) window.location.hash = `/${activeRoute}`;
      return { ...current, openRoutes: remaining, activeRoute };
    });
  };
  const toggleFavorite = (targetRoute: Route) => setWorkspace((current) => ({ ...current, favorites: current.favorites.includes(targetRoute) ? current.favorites.filter((item) => item !== targetRoute) : [...current.favorites, targetRoute] }));
  const paletteResults = SCREEN_REGISTRY.filter((screen) => `${screen.code} ${screen.label} ${screen.module} ${screen.description}`.toLocaleLowerCase('pt-BR').includes(paletteQuery.trim().toLocaleLowerCase('pt-BR'))).slice(0, 12);
  const activeScreen = screenForRoute(route);

  useEffect(() => { openScreen(route); }, [route]);
  useEffect(() => { try { window.localStorage.setItem(WORKSPACE_STORAGE_KEY, JSON.stringify(workspace)); } catch { /* armazenamento local indisponível */ } }, [workspace]);
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.ctrlKey && event.key.toLowerCase() === 'k') { event.preventDefault(); setPaletteOpen(true); }
      if (event.altKey && /^[1-9]$/.test(event.key)) { const target = workspace.openRoutes[Number(event.key) - 1]; if (target) { event.preventDefault(); openScreen(target); } }
      if (event.key === 'Escape') { setPaletteOpen(false); setClosePrompt(null); }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [workspace.openRoutes]);

  return <div className="app-shell"><aside className="sidebar"><div className="sidebar-brand"><span>F+</span><div><strong>Family+</strong><small>Workspace local</small></div></div><button className="quick-access" onClick={() => setPaletteOpen(true)} title="Acesso rápido (Ctrl + K)"><span>⌘</span><span>Ir para tela</span><kbd>Ctrl K</kbd></button><label className="menu-search"><span>⌕</span><input value={filter} onChange={(event) => setFilter(event.target.value)} placeholder="Filtrar módulos" aria-label="Filtrar módulos" /></label>{workspace.favorites.length > 0 && <section className="quick-list"><p>FAVORITOS</p>{workspace.favorites.map((favoriteRoute) => { const screen = screenForRoute(favoriteRoute); return <button key={screen.route} onClick={() => openScreen(screen.route)}>★ {screen.label}</button>; })}</section>}<nav className="navigation-tree" aria-label="Menu principal">{visibleGroups.map((group) => <section className={`nav-section ${activeGroup?.id === group.id ? 'has-active' : ''}`} key={group.id}><button className="nav-group-toggle" onClick={() => toggleGroup(group.id)} aria-expanded={isOpen(group.id)}><span className="nav-group-icon">{group.icon}</span><strong>{group.label}</strong><span className="nav-chevron">{isOpen(group.id) ? '⌃' : '⌄'}</span></button>{isOpen(group.id) && <div className="nav-children">{group.items.map((item) => <button className={`nav-item ${route === item.route ? 'active' : ''}`} key={item.route} onClick={() => openScreen(item.route)}><span className="nav-dot" />{item.label}</button>)}</div>}</section>)}</nav><div className="sidebar-foot"><span className="online-dot" /> Operação offline</div></aside><div className="main-area"><header><div><p className="eyebrow">{activeScreen.module} <span className="screen-code">{activeScreen.code}</span></p><h1>{activeScreen.label}</h1></div><div className="header-actions"><button className={`favorite-button ${workspace.favorites.includes(route) ? 'selected' : ''}`} onClick={() => toggleFavorite(route)} title="Adicionar ou remover dos favoritos">★</button><button className="palette-button" onClick={() => setPaletteOpen(true)}>⌘ <span>Ir para</span></button><div className="user-menu"><span className="avatar">{user.nome.slice(0, 1).toUpperCase()}</span><div><strong>{user.nome}</strong><button onClick={onLogout}>Sair</button></div></div></div></header><div className="workspace-tabs" role="tablist" aria-label="Telas abertas">{workspace.openRoutes.map((tabRoute, index) => { const screen = screenForRoute(tabRoute); return <div key={tabRoute} className={`workspace-tab ${route === tabRoute ? 'active' : ''}`} title={`${screen.code} · ${screen.module} > ${screen.label}`}><button role="tab" aria-selected={route === tabRoute} onClick={() => openScreen(tabRoute)}><span>{screen.icon}</span>{screen.label}</button>{tabRoute !== 'dashboard' && <button className="tab-close" onClick={() => setClosePrompt(tabRoute)} aria-label={`Fechar ${screen.label}`}>×</button>}<kbd>{index < 9 ? `Alt ${index + 1}` : ''}</kbd></div>; })}</div><main className="content workspace-content">{workspace.openRoutes.map((tabRoute) => <section key={tabRoute} className={`workspace-panel ${route === tabRoute ? 'active' : ''}`} aria-hidden={route !== tabRoute}><WorkspaceScreen route={tabRoute} notify={notify} openScreen={openScreen} /></section>)}</main></div>{paletteOpen && <CommandPalette query={paletteQuery} setQuery={setPaletteQuery} results={paletteQuery ? paletteResults : [...workspace.favorites, ...workspace.recentRoutes.filter((item) => !workspace.favorites.includes(item))].slice(0, 10).map(screenForRoute)} onClose={() => setPaletteOpen(false)} onOpen={(nextRoute) => { openScreen(nextRoute); setPaletteOpen(false); setPaletteQuery(''); }} onToggleFavorite={toggleFavorite} favorites={workspace.favorites} />}{closePrompt && <CloseTabDialog screen={screenForRoute(closePrompt)} onCancel={() => setClosePrompt(null)} onDiscard={() => { closeScreen(closePrompt); setClosePrompt(null); }} />}{toast && <div className={`toast ${toast.kind}`}>{toast.message}</div>}</div>;
}

function WorkspaceScreen({ route, notify, openScreen }: { route: Route; notify: (message: string, kind?: 'success' | 'error') => void; openScreen: (route: Route) => void }) {
  if (route.startsWith('dashboard')) return <Dashboard route={route} setRoute={openScreen} notify={notify} />;
  if (route === 'accounts' || route === 'categories') return <Module13Page route={route} notify={notify} />;
  if (route === 'members') return <FamilyAdminPage route="family/members" notify={notify} />;
  if (route.startsWith('family/')) return <FamilyAdminPage route={route} notify={notify} />;
  if (route === 'settings' || route.startsWith('settings/')) return <Sprint7SettingsPage route={route} notify={notify} />;
  if (route === 'planning' || route === 'planning/budget' || route === 'planning/actual-vs-planned') return <PlanningPage route={route} notify={notify} />;
  if (route.startsWith('transactions')) return <Module13Page route={route} notify={notify} />;
  if (route.startsWith('cards')) return <Module14Page route={route} notify={notify} />;
  if (route.startsWith('recurrences')) return <Module15Page route={route} notify={notify} />;
  return <ModuleHub screen={screenForRoute(route)} />;
}

function ModuleHub({ screen }: { screen: ScreenDefinition }) {
  return <><PageIntro title={screen.label} /><section className="module-hub"><div className="module-hub-mark">{screen.module.slice(0, 1)}</div><p className="eyebrow">{screen.module.toLocaleUpperCase('pt-BR')} <span className="screen-code">{screen.code}</span></p><h2>{screen.label}</h2><p>{screen.description}. Este hub local já participa do workspace: pode permanecer aberto em paralelo, ser favorito, ser localizado por código e ter seu contexto preservado na sessão.</p><div className="module-hub-meta"><span>Local e offline</span><span>{screen.permission}</span><span>Instância única</span></div></section><Card title="Próxima etapa deste módulo"><p>A implementação funcional será conectada às entidades, regras financeiras e relatórios correspondentes, preservando o modelo local e auditável do sistema.</p></Card></>;
}

function CommandPalette({ query, setQuery, results, onClose, onOpen, onToggleFavorite, favorites }: { query: string; setQuery: (value: string) => void; results: ScreenDefinition[]; onClose: () => void; onOpen: (route: Route) => void; onToggleFavorite: (route: Route) => void; favorites: Route[] }) {
  const [selected, setSelected] = useState(0);
  useEffect(() => setSelected(0), [query]);
  return <div className="palette-backdrop" onMouseDown={onClose}><section className="command-palette" role="dialog" aria-modal="true" aria-label="Acesso rápido" onMouseDown={(event) => event.stopPropagation()}><div className="palette-input"><span>⌘</span><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === 'ArrowDown') { event.preventDefault(); setSelected((current) => Math.min(current + 1, results.length - 1)); } if (event.key === 'ArrowUp') { event.preventDefault(); setSelected((current) => Math.max(current - 1, 0)); } if (event.key === 'Enter' && results[selected]) onOpen(results[selected].route); if (event.key === 'Escape') onClose(); }} placeholder="Pesquise por código ou nome da funcionalidade" /></div><p className="palette-hint">{query ? 'Resultados' : 'Favoritos e telas recentes'} · Use ↑ ↓ e Enter</p><div className="palette-results">{results.length === 0 ? <EmptyState text="Nenhuma funcionalidade encontrada." /> : results.map((screen, index) => <div className={`palette-result ${selected === index ? 'selected' : ''}`} key={screen.route}><button onMouseEnter={() => setSelected(index)} onClick={() => onOpen(screen.route)}><span className="palette-icon">{screen.icon}</span><span><strong>{screen.label}</strong><small>{screen.code} · {screen.module}</small></span></button><button className={`palette-favorite ${favorites.includes(screen.route) ? 'selected' : ''}`} onClick={() => onToggleFavorite(screen.route)} title="Favoritar">★</button></div>)}</div><footer><span>Ctrl + K para abrir</span><button onClick={onClose}>Esc para fechar</button></footer></section></div>;
}

function CloseTabDialog({ screen, onCancel, onDiscard }: { screen: ScreenDefinition; onCancel: () => void; onDiscard: () => void }) {
  return <div className="palette-backdrop"><section className="close-tab-dialog" role="dialog" aria-modal="true"><p className="eyebrow">FECHAR TELA</p><h2>Fechar “{screen.label}”?</h2><p>O contexto desta tela será removido das abas abertas. Como não há alterações pendentes, ela pode ser aberta novamente a qualquer momento pelo menu ou pelo acesso rápido.</p><div><Button tone="secondary" onClick={onCancel}>Cancelar</Button><Button onClick={onDiscard}>Fechar aba</Button></div></section></div>;
}

function financialHealthOf(summary: DashboardSummary) { return summary.saudeFinanceira; }
function healthValue(metric: FinancialHealth['taxaPoupanca'] | undefined, suffix = '') { return metric?.estado === 'calculado' && metric.valor !== null ? `${metric.valor.toLocaleString('pt-BR')}${suffix}` : metric?.estado === 'categorias_nao_configuradas' ? 'Configure as categorias essenciais para calcular sua reserva de emergência.' : 'Dados insuficientes para calcular'; }

function FinancialHealthPanel({ health, members, memberId, onSaved, onBack }: { health: FinancialHealth | null; members: Member[]; memberId: string; onSaved: () => void; onBack: () => void }) {
  const [categories, setCategories] = useState<Category[]>([]);
  const [reserve, setReserve] = useState('6');
  const [commitment, setCommitment] = useState('30');
  const [savingGoal, setSavingGoal] = useState('20');
  const [observation, setObservation] = useState('');
  const [essential, setEssential] = useState<string[]>([]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => { void api.categories().then((rows) => setCategories(rows.filter((item) => item.ativo && item.tipo === 'Despesa'))).catch((reason) => setError(reason instanceof Error ? reason.message : 'Não foi possível carregar as categorias.')); }, []);
  useEffect(() => {
    let active = true;
    void api.financialHealthProfile(memberId || undefined).then((profile) => {
      if (!active) return;
      setReserve(String(profile.metaReservaMeses));
      setCommitment(String(profile.tetoComprometimentoPercentual));
      setSavingGoal(profile.metaPoupancaPercentual == null ? '' : String(profile.metaPoupancaPercentual));
      setObservation(profile.observacao ?? '');
      setEssential(profile.categoriasEssenciais);
    }).catch((reason) => { if (active) setError(reason instanceof Error ? reason.message : 'Não foi possível carregar o perfil.'); });
    return () => { active = false; };
  }, [memberId]);

  const save = async (event: FormEvent) => {
    event.preventDefault(); setSaving(true); setError('');
    try {
      await api.saveFinancialHealthProfile({ membroId: memberId || null, metaReservaMeses: Number(reserve), tetoComprometimentoPercentual: Number(commitment), metaPoupancaPercentual: savingGoal.trim() ? Number(savingGoal) : null, observacao: observation, categoriasEssenciais: essential });
      onSaved();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível salvar o perfil.'); }
    finally { setSaving(false); }
  };
  const toggle = (id: string) => setEssential((items) => items.includes(id) ? items.filter((item) => item !== id) : [...items, id]);

  return <>
    <div className="modal-actions"><Button tone="secondary" onClick={onBack}>Voltar ao Dashboard</Button></div>
    <PageIntro title="Acompanhe metas e indicadores derivados dos dados financeiros efetivados. Os filtros de período e membro acima controlam esta análise." />
    <div className="metric-grid">
      <Metric title="Taxa de poupança" value={healthValue(health?.taxaPoupanca, '%')} tone="income" />
      <Metric title="Reserva de emergência" value={healthValue(health?.reservaEmergenciaMeses, ' meses')} tone="balance" />
      <Metric title="Comprometimento da renda" value={healthValue(health?.comprometimentoRenda, '%')} tone="expense" />
      <Metric title="Gastos fixos" value={healthValue(health?.gastosFixos, '%')} tone="expense" />
      <Metric title="Cobertura orçamentária" value={healthValue(health?.coberturaOrcamentaria, '%')} tone="result" />
    </div>
    <Card title="Perfil de saúde financeira">
      <p>Metas e categorias são salvas para a família ou como configuração específica do membro selecionado.</p>
      <form onSubmit={(event) => void save(event)}>
        <div className="form-grid">
          <Field label="Meta de reserva (meses)"><input type="number" min="1" max="60" step="0.5" value={reserve} onChange={(event) => setReserve(event.target.value)} required /></Field>
          <Field label="Teto de comprometimento (%)"><input type="number" min="0" max="100" step="0.1" value={commitment} onChange={(event) => setCommitment(event.target.value)} required /></Field>
          <Field label="Meta de poupança mensal (%)"><input type="number" min="0" max="100" step="0.1" value={savingGoal} onChange={(event) => setSavingGoal(event.target.value)} /></Field>
          <Field label="Escopo"><input readOnly value={memberId ? members.find((item) => item.id === memberId)?.nome ?? 'Membro' : 'Família'} /></Field>
        </div>
        <Field label="Observação da meta"><textarea rows={3} maxLength={1000} value={observation} onChange={(event) => setObservation(event.target.value)} /></Field>
        <fieldset className="health-categories">
          <legend>Categorias de despesas essenciais</legend>
          {categories.length ? categories.map((item) => <label key={item.id}><input type="checkbox" checked={essential.includes(item.id)} onChange={() => toggle(item.id)} />{item.nome}</label>) : <p className="form-hint">Nenhuma categoria de despesa ativa está configurada.</p>}
        </fieldset>
        {essential.length === 0 && <p className="form-hint health-warning">Configure as categorias essenciais para calcular sua reserva de emergência.</p>}
        {error && <p className="form-error" role="alert">{error}</p>}
        <div className="modal-actions"><Button type="submit" disabled={saving}>{saving ? 'Salvando…' : 'Salvar perfil'}</Button></div>
      </form>
    </Card>
  </>;
}

function Dashboard({ route, setRoute, notify }: { route: Route; setRoute: (route: Route) => void; notify: (message: string, kind?: 'success' | 'error') => void }) {
  const initialToday = localDateInput(new Date());
  const [summary, setSummary] = useState<DashboardSummary | null>(null); const [alerts, setAlerts] = useState<FinancialAlert[]>([]); const [members, setMembers] = useState<Member[]>([]); const [hasMovements, setHasMovements] = useState(true); const [horizon, setHorizon] = useState(30); const [memberId, setMemberId] = useState(''); const [period, setPeriod] = useState('month'); const [customStart, setCustomStart] = useState(`${initialToday.slice(0, 7)}-01`); const [customEnd, setCustomEnd] = useState(initialToday); const [busy, setBusy] = useState(true); const [dataRevision, setDataRevision] = useState(0);
  const periodDates = () => { const now = new Date(); const monthEnd = localDateInput(new Date(now.getFullYear(), now.getMonth() + 1, 0)); if (period === 'previous') { const start = new Date(now.getFullYear(), now.getMonth() - 1, 1); const previousEnd = new Date(now.getFullYear(), now.getMonth(), 0); return { dataInicio: localDateInput(start), dataFim: localDateInput(previousEnd) }; } if (period === 'three-months') return { dataInicio: localDateInput(new Date(now.getFullYear(), now.getMonth() - 2, 1)), dataFim: localDateInput(new Date(now.getFullYear(), now.getMonth() + 1, 0)) }; if (period === 'year') return { dataInicio: `${now.getFullYear()}-01-01`, dataFim: `${now.getFullYear()}-12-31` }; if (period === 'custom') return { dataInicio: customStart, dataFim: customEnd }; return { dataInicio: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`, dataFim: monthEnd }; };
  const load = async () => { if (period === 'custom' && (!customStart || !customEnd || customStart > customEnd)) return; setBusy(true); try { const dates = periodDates(); const query: DashboardQuery = { ...dates, horizonteDias: horizon, membroId: memberId || undefined }; const [dashboard, alertList, people, accounts, cards, transactions] = await Promise.all([api.dashboardSummary(query), api.alerts({ resolvido: false }), api.members(), api.accounts(), api.cards(), api.transactions({ pagina: 1, tamanhoPagina: 1 })]); setSummary(dashboard); setAlerts(alertList); setMembers(people.filter((item) => item.ativo)); setHasMovements(accounts.length > 0 || cards.length > 0 || transactions.totalItens > 0); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível carregar o Dashboard.', 'error'); } finally { setBusy(false); } };
  useEffect(() => { void load(); }, [horizon, memberId, period, customStart, customEnd, dataRevision]);
  useEffect(() => { const refresh = () => setDataRevision((revision) => revision + 1); window.addEventListener('familyplus:financial-data-changed', refresh); return () => window.removeEventListener('familyplus:financial-data-changed', refresh); }, []);
  const subroute = route.split('/').at(-1); if (busy && !summary) return <p>Carregando visão financeira…</p>;
  const current = summary ?? { saldo: { saldoConsolidadoCentavos: 0, contas: [] }, periodo: { receitasCentavos: 0, despesasCentavos: 0, resultadoCentavos: 0 }, projecao: { saldoAtualCentavos: 0, receitasPrevistasCentavos: 0, despesasPrevistasCentavos: 0, faturasPrevistasCentavos: 0, saldoProjetadoCentavos: 0, horizonteDias: horizon, dataInicio: today(), dataFim: today() }, fluxoCaixa: { dataInicio: today(), dataFim: today(), saldoInicialCentavos: 0, itens: [] }, proximasReceitas: [], proximasDespesas: [], cartoes: [], despesasCategorias: [], receitasCategorias: [], evolucao: [], kpis: { taxaPoupancaPercentual: 0, comprometimentoRendaPercentual: 0, gastosFixosPercentual: 0, proximasDespesasCentavos: 0, proximasReceitasCentavos: 0, alertasAbertos: 0 } } as DashboardSummary;
  const markRead = async (alert: FinancialAlert, resolve = false) => { try { resolve ? await api.resolveAlert(alert.id) : await api.markAlertRead(alert.id); setAlerts((items) => resolve ? items.filter((item) => item.id !== alert.id) : items.map((item) => item.id === alert.id ? { ...item, dataLeitura: new Date().toISOString() } : item)); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível atualizar o alerta.', 'error'); } };
  return <><DashboardFilters period={period} setPeriod={setPeriod} customStart={customStart} setCustomStart={setCustomStart} customEnd={customEnd} setCustomEnd={setCustomEnd} horizon={horizon} setHorizon={setHorizon} memberId={memberId} setMemberId={setMemberId} members={members} onRefresh={() => void load()} />{subroute === 'cash-flow' ? <CashFlowPanel summary={current} /> : subroute === 'alerts' ? <AlertsPanel alerts={alerts} onRead={markRead} /> : subroute === 'kpis' ? <KpisPanel summary={current} /> : subroute === 'health' ? <FinancialHealthPanel health={financialHealthOf(current) ?? null} members={members} memberId={memberId} onSaved={() => void load()} onBack={() => setRoute('dashboard')} /> : !hasMovements ? <section className="dashboard-empty"><p className="eyebrow">DASHBOARD FINANCEIRO</p><h2>Comece pela sua vida financeira local</h2><p>Cadastre contas, membros e movimentações para ver saldos, receitas, despesas e gráficos atualizados com os dados deste dispositivo.</p><div className="dashboard-empty-actions"><Button onClick={() => setRoute('accounts')}>Cadastrar conta</Button><Button tone="secondary" onClick={() => setRoute('members')}>Criar membro</Button><Button tone="secondary" onClick={() => setRoute('transactions')}>Registrar lançamento</Button></div></section> : <><section className="hero-card"><p className="eyebrow">VISÃO EXECUTIVA / V0.6</p><h2>Seu dinheiro, em um só lugar.</h2><p>Veja o saldo real, os compromissos futuros, o orçamento do mês e os sinais que pedem atenção, sempre derivados dos seus dados locais.</p><Button onClick={() => setRoute('transactions')}>Abrir movimentações</Button></section><div className="metric-grid"><Metric title="Saldo atual" value={money(current.saldo.saldoConsolidadoCentavos)} tone="balance" /><Metric title="Saldo projetado" value={money(current.projecao.saldoProjetadoCentavos)} tone={current.projecao.saldoProjetadoCentavos < 0 ? 'expense' : 'income'} /><Metric title="Receitas do período" value={money(current.periodo.receitasCentavos)} tone="income" /><Metric title="Despesas do período" value={money(current.periodo.despesasCentavos)} tone="expense" /></div><div className="metric-grid compact"><Metric title="Resultado" value={money(current.periodo.resultadoCentavos)} tone="result" /><Metric title="Taxa de poupança" value={healthValue(financialHealthOf(current)?.taxaPoupanca, '%')} tone="income" /><Metric title="Próximas despesas" value={money(current.kpis.proximasDespesasCentavos)} tone="expense" /><Metric title="Alertas ativos" value={String(alerts.length)} tone={alerts.some((item) => item.severidade === 'CRITICO') ? 'expense' : 'balance'} /></div><Card title="Saúde financeira"><div className="metric-grid compact"><Metric title="Reserva de emergência" value={healthValue(financialHealthOf(current)?.reservaEmergenciaMeses, ' meses')} tone="balance" /><Metric title="Comprometimento da renda" value={healthValue(financialHealthOf(current)?.comprometimentoRenda, '%')} tone="expense" /><Metric title="Gastos fixos" value={healthValue(financialHealthOf(current)?.gastosFixos, '%')} tone="expense" /><Metric title="Cobertura orçamentária" value={healthValue(financialHealthOf(current)?.coberturaOrcamentaria, '%')} tone="result" /></div><Button tone="secondary" onClick={() => setRoute('dashboard/health')}>Configurar metas e categorias essenciais</Button></Card>{current.orcamento && <DashboardBudgetCard budget={current.orcamento} onOpen={() => setRoute('planning/budget')} />}<div className="dashboard-grid"><Card title="Fluxo de caixa"><CashFlowMini summary={current} /></Card><Card title="Próximos vencimentos"><UpcomingList items={current.proximasDespesas.slice(0, 6)} empty="Nenhuma despesa prevista no horizonte." /></Card></div><div className="dashboard-grid"><Card title="Despesas por categoria"><CategoryBars categories={current.despesasCategorias} tone="expense" /></Card><Card title="Receitas x despesas"><MonthlyBars items={current.evolucao} /></Card></div><div className="dashboard-grid"><Card title="Contas"><AccountList accounts={current.saldo.contas} /></Card><Card title="Cartões"><CardList cards={current.cartoes} /></Card></div><Card title={`Alertas financeiros · ${alerts.length}`}><AlertsPanel alerts={alerts.slice(0, 5)} onRead={markRead} /></Card></>}</>;
}

function DashboardFilters({ period, setPeriod, customStart, setCustomStart, customEnd, setCustomEnd, horizon, setHorizon, memberId, setMemberId, members, onRefresh }: { period: string; setPeriod: (value: string) => void; customStart: string; setCustomStart: (value: string) => void; customEnd: string; setCustomEnd: (value: string) => void; horizon: number; setHorizon: (value: number) => void; memberId: string; setMemberId: (value: string) => void; members: Member[]; onRefresh: () => void }) { return <div className="dashboard-filters"><label>Período<select value={period} onChange={(event) => setPeriod(event.target.value)}><option value="month">Mês Atual</option><option value="previous">Mês Anterior</option><option value="three-months">Últimos 3 Meses</option><option value="year">Ano Vigente</option><option value="custom">Intervalo Customizado</option></select></label>{period === 'custom' && <><label>Data inicial<input type="date" value={customStart} max={customEnd || undefined} onChange={(event) => setCustomStart(event.target.value)} /></label><label>Data final<input type="date" value={customEnd} min={customStart || undefined} onChange={(event) => setCustomEnd(event.target.value)} /></label></>}<label>Horizonte<select value={horizon} onChange={(event) => setHorizon(Number(event.target.value))}><option value="7">7 dias</option><option value="15">15 dias</option><option value="30">30 dias</option><option value="60">60 dias</option><option value="90">90 dias</option></select></label><label>Membro<select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Todos</option>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></label><Button tone="secondary" onClick={onRefresh}>Atualizar</Button></div>; }
function CashFlowMini({ summary }: { summary: DashboardSummary }) { return summary.fluxoCaixa.itens.length === 0 ? <EmptyState text="Nenhum movimento previsto no horizonte." /> : <div className="table-scroll"><table><thead><tr><th>Data</th><th>Entradas</th><th>Saídas</th><th>Saldo projetado</th></tr></thead><tbody>{summary.fluxoCaixa.itens.slice(0, 8).map((item) => <tr key={item.data}><td>{date(item.data)}</td><td className="income-text">+{money(item.entradasRealizadasCentavos + item.entradasPrevistasCentavos)}</td><td className="expense-text">-{money(item.saidasRealizadasCentavos + item.saidasPrevistasCentavos + item.faturasCentavos)}</td><td>{money(item.saldoProjetadoCentavos)}</td></tr>)}</tbody></table></div>; }
function CashFlowPanel({ summary }: { summary: DashboardSummary }) { return <><PageIntro title={`Evolução de caixa dos próximos ${summary.projecao.horizonteDias} dias, separando realizado, previsto e faturas.`} /><Card title="Fluxo de caixa"><CashFlowMini summary={summary} /></Card><Card title="Saldo projetado acumulado"><MonthlyBars items={summary.evolucao} /></Card></>; }
function UpcomingList({ items, empty }: { items: Array<{ id: string; descricao: string; data: string; valorCentavos: number }>; empty: string }) { return items.length === 0 ? <EmptyState text={empty} /> : <ul className="upcoming-list">{items.map((item) => <li key={`${item.id}-${item.data}`}><span><strong>{item.descricao}</strong><small>{date(item.data)}</small></span><b className="expense-text">{money(item.valorCentavos)}</b></li>)}</ul>; }
function AccountList({ accounts }: { accounts: Array<{ contaId: string; contaNome: string; membroNome: string; saldoAtualCentavos: number }> }) { return accounts.length === 0 ? <EmptyState text="Nenhuma conta ativa." /> : <ul className="upcoming-list">{accounts.map((item) => <li key={item.contaId}><span><strong>{item.contaNome}</strong><small>{item.membroNome}</small></span><b>{money(item.saldoAtualCentavos)}</b></li>)}</ul>; }
function CardList({ cards }: { cards: Array<{ cartaoId: string; nome: string; faturaAtualCentavos: number; vencimento?: string; limiteDisponivelCentavos: number; percentualUtilizado: number }> }) { return cards.length === 0 ? <EmptyState text="Nenhum cartão ativo." /> : <ul className="upcoming-list">{cards.map((item) => <li key={item.cartaoId}><span><strong>{item.nome}</strong><small>Fatura atual {money(item.faturaAtualCentavos)} · {item.percentualUtilizado}% usado</small></span><b>{money(item.limiteDisponivelCentavos)} disponível</b></li>)}</ul>; }
function CategoryBars({ categories, tone }: { categories: Array<{ categoriaNome: string; valorCentavos: number; percentual: number }>; tone: string }) { return categories.length === 0 ? <EmptyState text="Nenhuma categoria no período." /> : <div className="bar-list">{categories.slice(0, 8).map((item) => <div key={item.categoriaNome}><div><span>{item.categoriaNome}</span><b>{money(item.valorCentavos)}</b></div><i className={tone} style={{ width: `${Math.min(100, Math.max(2, item.percentual))}%` }} /></div>)}</div>; }
function MonthlyBars({ items }: { items: Array<{ competencia: string; receitasCentavos: number; despesasCentavos: number; resultadoCentavos: number }> }) { return <div className="bar-list monthly-bars">{items.map((item) => { const max = Math.max(item.receitasCentavos, item.despesasCentavos, 1); return <div key={item.competencia}><div><span>{new Intl.DateTimeFormat('pt-BR', { month: 'short' }).format(new Date(item.competencia))}</span><b>{money(item.resultadoCentavos)}</b></div><i className="income" style={{ width: `${(item.receitasCentavos / max) * 100}%` }} /><i className="expense" style={{ width: `${(item.despesasCentavos / max) * 100}%` }} /></div>; })}</div>; }
function KpisPanel({ summary }: { summary: DashboardSummary }) { const health = financialHealthOf(summary); return <><PageIntro title="Indicadores objetivos para acompanhar poupança, renda comprometida e rigidez dos gastos." /><div className="metric-grid"><Metric title="Taxa de poupança" value={healthValue(health?.taxaPoupanca, "%")} tone="income" /><Metric title="Comprometimento da renda" value={healthValue(health?.comprometimentoRenda, "%")} tone="expense" /><Metric title="Gastos fixos" value={healthValue(health?.gastosFixos, "%")} tone="expense" /><Metric title="Saldo projetado" value={money(summary.projecao.saldoProjetadoCentavos)} tone="result" /></div><div className="dashboard-grid"><Card title="Receitas por categoria"><CategoryBars categories={summary.receitasCategorias} tone="income" /></Card><Card title="Evolução mensal"><MonthlyBars items={summary.evolucao} /></Card></div></>; }
function AlertsPanel({ alerts, onRead }: { alerts: FinancialAlert[]; onRead: (alert: FinancialAlert, resolve?: boolean) => Promise<void> }) { return alerts.length === 0 ? <EmptyState text="Nenhum alerta financeiro aberto." /> : <ul className="alert-list">{alerts.map((alert) => <li key={alert.id} className={alert.severidade.toLowerCase()}><span className="alert-icon">{alert.severidade === 'CRITICO' ? '!' : alert.severidade === 'ATENCAO' ? '!' : 'i'}</span><div><strong>{alert.titulo}</strong><p>{alert.mensagem}</p><small>{date(alert.dataGeracao)}</small></div><div className="actions"><button onClick={() => void onRead(alert)}>Lido</button><button onClick={() => void onRead(alert, true)}>Resolver</button></div></li>)}</ul>; }

function localDateInput(value: Date) { return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`; }
function today() { return new Date().toISOString().slice(0, 10); }
function isoDate(date: string) { return new Date(`${date}T12:00:00`).toISOString(); }
function transactionLabel(type: TransactionType) { return type === 'RECEITA' ? 'Receita' : type === 'DESPESA' ? 'Despesa' : type === 'TRANSFERENCIA_ENTRADA' ? 'Transferência recebida' : 'Transferência enviada'; }
function statusLabel(status: TransactionStatus) { return status === 'EFETIVADA' ? 'Efetivada' : status === 'PREVISTA' ? 'Prevista' : 'Cancelada'; }
function signedMoney(item: Transaction) { const positive = item.tipo === 'RECEITA' || item.tipo === 'TRANSFERENCIA_ENTRADA'; return `${positive ? '+' : '-'}${money(item.valorCentavos)}`; }
function Metric({ title, value, tone }: { title: string; value: string; tone: string }) { return <section className={`metric ${tone}`}><span>{title}</span><strong>{value}</strong></section>; }

function TransactionsPage({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [items, setItems] = useState<Transaction[]>([]); const [accounts, setAccounts] = useState<Account[]>([]); const [members, setMembers] = useState<Member[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [summary, setSummary] = useState<{ receitasCentavos: number; despesasCentavos: number; resultadoCentavos: number }>({ receitasCentavos: 0, despesasCentavos: 0, resultadoCentavos: 0 });
  const [totalPages, setTotalPages] = useState(0); const [page, setPage] = useState(1); const [editing, setEditing] = useState<Transaction | null | undefined>(undefined); const [transferEditing, setTransferEditing] = useState<Transfer | null | undefined>(undefined); const [transfers, setTransfers] = useState<Transfer[]>([]);
  const [filters, setFilters] = useState({ dataInicio: '', dataFim: '', contaId: '', membroId: '', categoriaId: '', tipo: '', status: '', texto: '', ordenarPor: 'data', desc: true });
  const load = async () => { try { const query = { ...filters, pagina: page, tamanhoPagina: 10 }; const [result, people, accountList, categoryList, month, transferList] = await Promise.all([api.transactions(query), api.members(), api.accounts(), api.categories(), api.transactionsSummary({ dataInicio: filters.dataInicio || undefined, dataFim: filters.dataFim || undefined }), api.transfers()]); setItems(result.items); setTotalPages(result.totalPaginas); setMembers(people.filter((item) => item.ativo)); setAccounts(accountList); setCategories(categoryList); setSummary(month); setTransfers(transferList); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar movimentações.', 'error'); } };
  useEffect(() => { void load(); }, [filters, page]);
  const updateFilter = (key: string, value: string) => { setPage(1); setFilters((current) => ({ ...current, [key]: value })); };
  const saveTransaction = async (payload: TransactionRequest) => { try { editing?.id ? await api.updateTransaction(editing.id, payload) : await api.createTransaction(payload); notify(editing?.id ? 'Movimentação atualizada.' : 'Movimentação cadastrada.'); setEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar movimentação.', 'error'); } };
  const saveTransfer = async (payload: TransferRequest) => { try { transferEditing ? await api.updateTransfer(transferEditing.id, payload) : await api.createTransfer(payload); notify(transferEditing ? 'Transferência atualizada.' : 'Transferência cadastrada.'); setTransferEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar transferência.', 'error'); } };
  const cancel = async (item: Transaction) => { if (!window.confirm(`Cancelar ${item.descricao}?`)) return; try { await api.cancelTransaction(item.id); notify('Movimentação cancelada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao cancelar.', 'error'); } };
  const cancelTransfer = async (item: Transfer) => { if (!window.confirm(`Cancelar a transferência ${item.descricao}?`)) return; try { await api.cancelTransfer(item.id); notify('Transferência cancelada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao cancelar.', 'error'); } };
  const clearFilters = () => { setPage(1); setFilters({ dataInicio: '', dataFim: '', contaId: '', membroId: '', categoriaId: '', tipo: '', status: '', texto: '', ordenarPor: 'data', desc: true }); };
  return <><PageIntro title="Acompanhe tudo que entra, sai ou muda de conta." action={<div className="page-actions"><Button onClick={() => setEditing(null)}>Nova receita</Button><Button tone="secondary" onClick={() => setEditing({} as Transaction)}>Nova despesa</Button><Button tone="secondary" onClick={() => setTransferEditing(null)}>Transferir</Button></div>} /><div className="metric-grid compact"><Metric title="Receitas no período" value={money(summary.receitasCentavos)} tone="income" /><Metric title="Despesas no período" value={money(summary.despesasCentavos)} tone="expense" /><Metric title="Resultado" value={money(summary.resultadoCentavos)} tone="result" /></div><Card title="Filtros e busca"><div className="filter-grid"><Field label="Busca"><input value={filters.texto} onChange={(event) => updateFilter('texto', event.target.value)} placeholder="Descrição" /></Field><Field label="De"><input value={filters.dataInicio} onChange={(event) => updateFilter('dataInicio', event.target.value)} type="date" /></Field><Field label="Até"><input value={filters.dataFim} onChange={(event) => updateFilter('dataFim', event.target.value)} type="date" /></Field><Field label="Conta"><select value={filters.contaId} onChange={(event) => updateFilter('contaId', event.target.value)}><option value="">Todas</option>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Membro"><select value={filters.membroId} onChange={(event) => updateFilter('membroId', event.target.value)}><option value="">Todos</option>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Categoria"><select value={filters.categoriaId} onChange={(event) => updateFilter('categoriaId', event.target.value)}><option value="">Todas</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Tipo"><select value={filters.tipo} onChange={(event) => updateFilter('tipo', event.target.value)}><option value="">Todos</option><option value="RECEITA">Receita</option><option value="DESPESA">Despesa</option><option value="TRANSFERENCIA_ENTRADA">Transferência recebida</option><option value="TRANSFERENCIA_SAIDA">Transferência enviada</option></select></Field><Field label="Status"><select value={filters.status} onChange={(event) => updateFilter('status', event.target.value)}><option value="">Todos</option><option value="EFETIVADA">Efetivada</option><option value="PREVISTA">Prevista</option><option value="CANCELADA">Cancelada</option></select></Field><Field label="Ordenar por"><select value={filters.ordenarPor} onChange={(event) => updateFilter('ordenarPor', event.target.value)}><option value="data">Data</option><option value="valor">Valor</option><option value="descricao">Descrição</option></select></Field><Field label="Direção"><select value={filters.desc ? 'desc' : 'asc'} onChange={(event) => updateFilter('desc', event.target.value === 'desc' ? 'true' : 'false')}><option value="desc">Mais recentes / maior</option><option value="asc">Mais antigos / menor</option></select></Field></div><Button tone="secondary" onClick={clearFilters}>Limpar filtros</Button></Card><Card title={`Transações${items.length ? ` · ${items.length} nesta página` : ''}`}><div className="table-scroll">{items.length === 0 ? <EmptyState text="Nenhuma movimentação encontrada para os filtros atuais." /> : <table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Conta</th><th>Tipo</th><th>Valor</th><th>Status</th><th /></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td>{date(item.dataMovimentacao)}</td><td><strong>{item.descricao}</strong><small>{item.membroNome}</small></td><td>{item.categoriaNome || 'Transferência'}</td><td>{item.contaNome}</td><td><span className={`type-tag ${item.tipo === 'RECEITA' || item.tipo === 'TRANSFERENCIA_ENTRADA' ? 'income' : 'expense'}`}>{transactionLabel(item.tipo)}</span></td><td className={item.tipo === 'RECEITA' || item.tipo === 'TRANSFERENCIA_ENTRADA' ? 'amount income-text' : 'amount expense-text'}>{signedMoney(item)}</td><td><span className={`status ${item.status.toLowerCase()}`}>{statusLabel(item.status)}</span></td><td className="actions">{item.transferenciaId ? <button onClick={() => setTransferEditing(transfers.find((transfer) => transfer.id === item.transferenciaId) ?? null)}>Editar</button> : <button onClick={() => setEditing(item)}>Editar</button>}{item.status !== 'CANCELADA' && <button onClick={() => void cancel(item)}>Cancelar</button>}</td></tr>)}</tbody></table>}</div>{totalPages > 0 && <div className="pagination"><span>Página {page} de {totalPages}</span><div><Button tone="secondary" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Anterior</Button><Button tone="secondary" disabled={page >= totalPages} onClick={() => setPage((value) => value + 1)}>Próxima</Button></div></div>}</Card>{transfers.filter((item) => !items.some((movement) => movement.transferenciaId === item.id)).map((item) => <div key={item.id} className="transfer-row"><span>Transferência {item.descricao}: {item.contaOrigemNome} → {item.contaDestinoNome} · {money(item.valorCentavos)}</span><span className={`status ${item.status.toLowerCase()}`}>{statusLabel(item.status)}</span><span className="actions"><button onClick={() => setTransferEditing(item)}>Editar</button>{item.status !== 'CANCELADA' && <button onClick={() => void cancelTransfer(item)}>Cancelar</button>}</span></div>)}{editing !== undefined && <TransactionModal transaction={editing?.id ? editing : null} mode={editing?.id && editing.tipo === 'DESPESA' ? 'DESPESA' : editing?.id ? 'RECEITA' : editing === null ? 'RECEITA' : 'DESPESA'} accounts={accounts.filter((item) => item.ativo)} members={members} categories={categories.filter((item) => item.ativo)} onClose={() => setEditing(undefined)} onSave={saveTransaction} />}{transferEditing !== undefined && <TransferModal transfer={transferEditing} accounts={accounts.filter((item) => item.ativo)} members={members} onClose={() => setTransferEditing(undefined)} onSave={saveTransfer} />}</>;
}

function TransactionModal({ transaction, mode, accounts, members, categories, onClose, onSave }: { transaction: Transaction | null; mode: 'RECEITA' | 'DESPESA'; accounts: Account[]; members: Member[]; categories: Category[]; onClose: () => void; onSave: (payload: TransactionRequest) => Promise<void> }) {
  const [descricao, setDescricao] = useState(transaction?.descricao ?? ''); const [valor, setValor] = useState(transaction ? String(transaction.valorCentavos / 100) : ''); const [data, setData] = useState(transaction ? transaction.dataMovimentacao.slice(0, 10) : today()); const [contaId, setContaId] = useState(transaction?.contaId ?? accounts[0]?.id ?? ''); const [membroId, setMembroId] = useState(transaction?.membroId ?? members[0]?.id ?? ''); const [categoriaId, setCategoriaId] = useState(transaction?.categoriaId ?? categories.find((item) => item.tipo === (mode === 'RECEITA' ? 'Receita' : 'Despesa'))?.id ?? ''); const [status, setStatus] = useState<TransactionStatus>(transaction?.status ?? 'EFETIVADA'); const [observacao, setObservacao] = useState(transaction?.observacao ?? ''); const [busy, setBusy] = useState(false); const availableCategories = categories.filter((item) => item.tipo === (mode === 'RECEITA' ? 'Receita' : 'Despesa'));
  return <Modal title={`${transaction ? 'Editar' : 'Nova'} ${mode === 'RECEITA' ? 'receita' : 'despesa'}`} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ tipo: mode, descricao, valorCentavos: Math.round(Number(valor.replace(',', '.')) * 100), dataCompetencia: isoDate(data), dataMovimentacao: isoDate(data), contaId, categoriaId, membroId, status, observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Descrição"><input value={descricao} onChange={(event) => setDescricao(event.target.value)} autoFocus placeholder="Ex.: Mercado" /></Field><Field label="Valor (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" placeholder="0,00" /></Field><Field label="Data"><input value={data} onChange={(event) => setData(event.target.value)} type="date" /></Field><Field label="Conta"><select value={contaId} onChange={(event) => setContaId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Categoria"><select value={categoriaId} onChange={(event) => setCategoriaId(event.target.value)}>{availableCategories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Status"><select value={status} onChange={(event) => setStatus(event.target.value as TransactionStatus)}><option value="EFETIVADA">Efetivada</option><option value="PREVISTA">Prevista</option><option value="CANCELADA">Cancelada</option></select></Field></div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={3} placeholder="Opcional" /></Field><p className="form-hint">Somente movimentações efetivadas alteram o saldo. A categoria precisa ser compatível com o tipo.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || accounts.length === 0 || members.length === 0 || availableCategories.length === 0}>{busy ? 'Salvando…' : 'Salvar movimentação'}</Button></div></Form></Modal>;
}

function TransferModal({ transfer, accounts, members, onClose, onSave }: { transfer: Transfer | null; accounts: Account[]; members: Member[]; onClose: () => void; onSave: (payload: TransferRequest) => Promise<void> }) {
  const [origem, setOrigem] = useState(transfer?.contaOrigemId ?? accounts[0]?.id ?? ''); const [destino, setDestino] = useState(transfer?.contaDestinoId ?? accounts[1]?.id ?? accounts[0]?.id ?? ''); const [membroId, setMembroId] = useState(transfer?.membroId ?? members[0]?.id ?? ''); const [valor, setValor] = useState(transfer ? String(transfer.valorCentavos / 100) : ''); const [data, setData] = useState(transfer ? transfer.data.slice(0, 10) : today()); const [descricao, setDescricao] = useState(transfer?.descricao ?? ''); const [status, setStatus] = useState<TransactionStatus>(transfer?.status ?? 'EFETIVADA'); const [busy, setBusy] = useState(false);
  return <Modal title={transfer ? 'Editar transferência' : 'Nova transferência'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ contaOrigemId: origem, contaDestinoId: destino, membroId, valorCentavos: Math.round(Number(valor.replace(',', '.')) * 100), data: isoDate(data), descricao, status }); setBusy(false); }}><div className="form-grid"><Field label="Conta de origem"><select value={origem} onChange={(event) => setOrigem(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Conta de destino"><select value={destino} onChange={(event) => setDestino(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Valor (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" /></Field><Field label="Data"><input value={data} onChange={(event) => setData(event.target.value)} type="date" /></Field><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Status"><select value={status} onChange={(event) => setStatus(event.target.value as TransactionStatus)}><option value="EFETIVADA">Efetivada</option><option value="PREVISTA">Prevista</option><option value="CANCELADA">Cancelada</option></select></Field></div><Field label="Descrição"><input value={descricao} onChange={(event) => setDescricao(event.target.value)} placeholder="Ex.: Reserva mensal" /></Field><p className="form-hint">A transferência gera saída e entrada vinculadas; o patrimônio total permanece igual.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || accounts.length < 2 || members.length === 0}>{busy ? 'Salvando…' : 'Salvar transferência'}</Button></div></Form></Modal>;
}

function MembersPage({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [items, setItems] = useState<Member[]>([]); const [editing, setEditing] = useState<Member | null | undefined>(undefined);
  const load = async () => { try { setItems(await api.members()); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar membros.', 'error'); } };
  useEffect(() => { void load(); }, []);
  const save = async (payload: { nome: string; descricao?: string }) => { try { editing ? await api.updateMember(editing.id, payload) : await api.createMember(payload); notify(editing ? 'Membro atualizado.' : 'Membro cadastrado.'); setEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar.', 'error'); } };
  return <><PageIntro title="Pessoas que participam deste espaço financeiro." action={<Button onClick={() => setEditing(null)}>Adicionar membro</Button>} /><Card title="Membros cadastrados">{items.length === 0 ? <EmptyState text="Nenhum membro cadastrado ainda." /> : <table><thead><tr><th>Nome</th><th>Descrição</th><th>Situação</th><th /></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td><strong>{item.nome}</strong><small>Desde {date(item.criadoEm)}</small></td><td>{item.descricao || '—'}</td><td><Status active={item.ativo} /></td><td className="actions"><button onClick={() => setEditing(item)}>Editar</button><button onClick={async () => { if (window.confirm(`Deseja ${item.ativo ? 'desativar' : 'ativar'} ${item.nome}?`)) { try { await api.memberStatus(item.id, !item.ativo); notify('Situação atualizada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar.', 'error'); } } }}>{item.ativo ? 'Desativar' : 'Ativar'}</button></td></tr>)}</tbody></table>}</Card>{editing !== undefined && <MemberModal member={editing} onClose={() => setEditing(undefined)} onSave={save} />}</>;
}

function MemberModal({ member, onClose, onSave }: { member: Member | null; onClose: () => void; onSave: (payload: { nome: string; descricao?: string }) => Promise<void> }) { const [nome, setNome] = useState(member?.nome ?? ''); const [descricao, setDescricao] = useState(member?.descricao ?? ''); const [busy, setBusy] = useState(false); return <Modal title={member ? 'Editar membro' : 'Novo membro'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ nome, descricao: descricao || undefined }); setBusy(false); }}><Field label="Nome"><input value={nome} onChange={(event) => setNome(event.target.value)} autoFocus /></Field><Field label="Descrição"><textarea value={descricao} onChange={(event) => setDescricao(event.target.value)} placeholder="Opcional" rows={3} /></Field><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy}>{busy ? 'Salvando…' : 'Salvar membro'}</Button></div></Form></Modal>; }

function AccountsPage({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [items, setItems] = useState<Account[]>([]); const [members, setMembers] = useState<Member[]>([]); const [balances, setBalances] = useState<Record<string, AccountBalance>>({}); const [editing, setEditing] = useState<Account | null | undefined>(undefined); const [statementAccount, setStatementAccount] = useState<Account | null>(null);
  const load = async () => { try { const [accounts, people] = await Promise.all([api.accounts(), api.members()]); const currentBalances = await Promise.all(accounts.map((account) => api.accountBalance(account.id))); setItems(accounts); setMembers(people.filter((member) => member.ativo)); setBalances(Object.fromEntries(currentBalances.map((balance) => [balance.contaId, balance]))); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar contas.', 'error'); } };
  useEffect(() => { void load(); }, []);
  const save = async (payload: Omit<Account, 'id' | 'membroNome' | 'ativo'>) => { try { editing ? await api.updateAccount(editing.id, payload) : await api.createAccount(payload); notify(editing ? 'Conta atualizada.' : 'Conta cadastrada.'); setEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar.', 'error'); } };
  return <><PageIntro title="Cadastre onde o dinheiro está antes das movimentações." action={<Button onClick={() => setEditing(null)} disabled={members.length === 0}>Adicionar conta</Button>} />{members.length === 0 && <p className="inline-warning">Cadastre e mantenha ao menos um membro ativo antes de criar contas.</p>}<Card title="Contas financeiras">{items.length === 0 ? <EmptyState text="Nenhuma conta financeira cadastrada ainda." /> : <table><thead><tr><th>Conta</th><th>Membro</th><th>Tipo</th><th>Saldo inicial</th><th>Saldo atual</th><th>Situação</th><th /></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td><strong>{item.nome}</strong><small>{item.observacao || 'Sem observação'}</small></td><td>{item.membroNome}</td><td>{accountTypes.find((type) => type.value === item.tipo)?.label}</td><td>{money(item.saldoInicialCentavos)}</td><td><strong>{balances[item.id] ? money(balances[item.id].saldoAtualCentavos) : '…'}</strong></td><td><Status active={item.ativo} /></td><td className="actions"><button onClick={() => setStatementAccount(item)}>Extrato</button><button onClick={() => setEditing(item)}>Editar</button><button onClick={async () => { if (window.confirm(`Deseja ${item.ativo ? 'desativar' : 'ativar'} ${item.nome}?`)) { try { await api.accountStatus(item.id, !item.ativo); notify('Situação atualizada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar.', 'error'); } } }}>{item.ativo ? 'Desativar' : 'Ativar'}</button></td></tr>)}</tbody></table>}</Card>{editing !== undefined && <AccountModal account={editing} members={members} onClose={() => setEditing(undefined)} onSave={save} />}{statementAccount && <StatementModal account={statementAccount} onClose={() => setStatementAccount(null)} notify={notify} />}</>;
}

function AccountModal({ account, members, onClose, onSave }: { account: Account | null; members: Member[]; onClose: () => void; onSave: (payload: Omit<Account, 'id' | 'membroNome' | 'ativo'>) => Promise<void> }) { const [nome, setNome] = useState(account?.nome ?? ''); const [membroId, setMembroId] = useState(account?.membroId ?? members[0]?.id ?? ''); const [tipo, setTipo] = useState<AccountType>(account?.tipo ?? 'ContaCorrente'); const [saldo, setSaldo] = useState(String((account?.saldoInicialCentavos ?? 0) / 100)); const [observacao, setObservacao] = useState(account?.observacao ?? ''); const [busy, setBusy] = useState(false); return <Modal title={account ? 'Editar conta' : 'Nova conta'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ membroId, nome, tipo, saldoInicialCentavos: Math.round(Number(saldo.replace(',', '.')) * 100), observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Nome"><input value={nome} onChange={(event) => setNome(event.target.value)} autoFocus /></Field><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((member) => <option key={member.id} value={member.id}>{member.nome}</option>)}</select></Field><Field label="Tipo"><select value={tipo} onChange={(event) => setTipo(event.target.value as AccountType)}>{accountTypes.map((type) => <option key={type.value} value={type.value}>{type.label}</option>)}</select></Field><Field label="Saldo inicial (R$)"><input value={saldo} onChange={(event) => setSaldo(event.target.value)} type="number" step="0.01" /></Field></div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} placeholder="Opcional" rows={3} /></Field><p className="form-hint">O saldo inicial será preservado separadamente das movimentações futuras.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy}>{busy ? 'Salvando…' : 'Salvar conta'}</Button></div></Form></Modal>; }

function CategoriesPage({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [items, setItems] = useState<Category[]>([]); const [editing, setEditing] = useState<Category | null | undefined>(undefined);
  const load = async () => { try { setItems(await api.categories()); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar categorias.', 'error'); } };
  useEffect(() => { void load(); }, []);
  const save = async (payload: { nome: string; tipo: CategoryType; categoriaPaiId?: string }) => { try { editing ? await api.updateCategory(editing.id, payload) : await api.createCategory(payload); notify(editing ? 'Categoria atualizada.' : 'Categoria cadastrada.'); setEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar.', 'error'); } };
  return <><PageIntro title="Estruture receitas e despesas em uma hierarquia simples." action={<Button onClick={() => setEditing(null)}>Adicionar categoria</Button>} /><Card title="Categorias">{items.length === 0 ? <EmptyState text="Nenhuma categoria cadastrada ainda." /> : <table><thead><tr><th>Categoria</th><th>Tipo</th><th>Categoria pai</th><th>Situação</th><th /></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td><strong>{item.categoriaPaiId ? '↳ ' : ''}{item.nome}</strong></td><td><span className={`type-tag ${item.tipo === 'Receita' ? 'income' : 'expense'}`}>{item.tipo}</span></td><td>{item.categoriaPaiNome || '—'}</td><td><Status active={item.ativo} /></td><td className="actions"><button onClick={() => setEditing(item)}>Editar</button><button onClick={async () => { if (window.confirm(`Deseja ${item.ativo ? 'desativar' : 'ativar'} ${item.nome}?`)) { try { await api.categoryStatus(item.id, !item.ativo); notify('Situação atualizada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar.', 'error'); } } }}>{item.ativo ? 'Desativar' : 'Ativar'}</button></td></tr>)}</tbody></table>}</Card>{editing !== undefined && <CategoryModal category={editing} all={items} onClose={() => setEditing(undefined)} onSave={save} />}</>;
}

function CategoryModal({ category, all, onClose, onSave }: { category: Category | null; all: Category[]; onClose: () => void; onSave: (payload: { nome: string; tipo: CategoryType; categoriaPaiId?: string }) => Promise<void> }) { const [nome, setNome] = useState(category?.nome ?? ''); const [tipo, setTipo] = useState<CategoryType>(category?.tipo ?? 'Despesa'); const [parent, setParent] = useState(category?.categoriaPaiId ?? ''); const [busy, setBusy] = useState(false); const candidates = all.filter((item) => item.id !== category?.id && item.tipo === tipo); return <Modal title={category ? 'Editar categoria' : 'Nova categoria'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ nome, tipo, categoriaPaiId: parent || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Nome"><input value={nome} onChange={(event) => setNome(event.target.value)} autoFocus /></Field><Field label="Tipo"><select value={tipo} onChange={(event) => { setTipo(event.target.value as CategoryType); setParent(''); }}><option value="Despesa">Despesa</option><option value="Receita">Receita</option></select></Field></div><Field label="Categoria pai (opcional)"><select value={parent} onChange={(event) => setParent(event.target.value)}><option value="">Nenhuma — categoria principal</option>{candidates.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><p className="form-hint">Categorias pai e filha precisam ter o mesmo tipo. A API impede ciclos na hierarquia.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy}>{busy ? 'Salvando…' : 'Salvar categoria'}</Button></div></Form></Modal>; }

function StatementModal({ account, onClose, notify }: { account: Account; onClose: () => void; notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [statement, setStatement] = useState<{ resumo: { saldoInicialCentavos: number; entradasCentavos: number; saidasCentavos: number; saldoAtualCentavos: number }; movimentacoes: Transaction[] } | null>(null); const [dataInicio, setDataInicio] = useState(''); const [dataFim, setDataFim] = useState('');
  const load = async () => { try { setStatement(await api.accountStatement(account.id, { dataInicio, dataFim })); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar extrato.', 'error'); } };
  useEffect(() => { void load(); }, []);
  return <Modal title={`Extrato · ${account.nome}`} onClose={onClose}><div className="statement-filters"><Field label="De"><input type="date" value={dataInicio} onChange={(event) => setDataInicio(event.target.value)} /></Field><Field label="Até"><input type="date" value={dataFim} onChange={(event) => setDataFim(event.target.value)} /></Field><Button tone="secondary" onClick={() => void load()}>Filtrar</Button></div>{statement ? <><div className="statement-summary"><div><span>Saldo inicial</span><strong>{money(statement.resumo.saldoInicialCentavos)}</strong></div><div><span>Entradas</span><strong className="income-text">+{money(statement.resumo.entradasCentavos)}</strong></div><div><span>Saídas</span><strong className="expense-text">-{money(statement.resumo.saidasCentavos)}</strong></div><div><span>Saldo atual</span><strong>{money(statement.resumo.saldoAtualCentavos)}</strong></div></div><div className="table-scroll"><table><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Valor</th><th>Status</th></tr></thead><tbody>{statement.movimentacoes.map((item) => <tr key={item.id}><td>{date(item.dataMovimentacao)}</td><td>{item.descricao}</td><td>{transactionLabel(item.tipo)}</td><td className={item.tipo === 'RECEITA' || item.tipo === 'TRANSFERENCIA_ENTRADA' ? 'income-text' : 'expense-text'}>{signedMoney(item)}</td><td>{statusLabel(item.status)}</td></tr>)}</tbody></table></div></> : <p>Carregando extrato…</p>}</Modal>;
}

function invoiceStatus(status: InvoiceStatus) { return status === 'ABERTA' ? 'Aberta' : status === 'FECHADA' ? 'Fechada' : status === 'PAGA' ? 'Paga' : status === 'VENCIDA' ? 'Vencida' : 'Cancelada'; }
function CardsPage({ notify }: { notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [cards, setCards] = useState<CreditCard[]>([]); const [limits, setLimits] = useState<Record<string, CardLimit>>({}); const [members, setMembers] = useState<Member[]>([]); const [accounts, setAccounts] = useState<Account[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [purchases, setPurchases] = useState<CardPurchase[]>([]); const [invoices, setInvoices] = useState<Invoice[]>([]); const [editingCard, setEditingCard] = useState<CreditCard | null | undefined>(undefined); const [purchaseOpen, setPurchaseOpen] = useState(false); const [paymentInvoice, setPaymentInvoice] = useState<Invoice | null>(null); const [invoiceDetail, setInvoiceDetail] = useState<InvoiceDetail | null>(null);
  const load = async () => { try { const [cardList, people, accountList, categoryList] = await Promise.all([api.cards(), api.members(), api.accounts(), api.categories()]); const [limitList, invoiceList, purchaseList] = await Promise.all([Promise.all(cardList.map((card) => api.cardLimit(card.id))), api.invoices(), api.cardPurchases()]); setCards(cardList); setLimits(Object.fromEntries(limitList.map((limit) => [limit.cartaoId, limit]))); setMembers(people.filter((item) => item.ativo)); setAccounts(accountList.filter((item) => item.ativo)); setCategories(categoryList.filter((item) => item.ativo && item.tipo === 'Despesa')); setInvoices(invoiceList); setPurchases(purchaseList); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar cartões.', 'error'); } };
  useEffect(() => { void load(); }, []);
  const saveCard = async (payload: CardRequest) => { try { editingCard?.id ? await api.updateCard(editingCard.id, payload) : await api.createCard(payload); notify(editingCard?.id ? 'Cartão atualizado.' : 'Cartão cadastrado.'); setEditingCard(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar cartão.', 'error'); } };
  const savePurchase = async (payload: CardPurchaseRequest) => { try { await api.createCardPurchase(payload); notify('Compra no cartão cadastrada.'); setPurchaseOpen(false); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar compra.', 'error'); } };
  const pay = async (invoice: Invoice, accountId: string) => { try { await api.payInvoice(invoice.id, { contaPagamentoId: accountId, dataPagamento: isoDate(today()), valorCentavos: invoice.valorTotalCentavos }); notify('Fatura paga e saldo da conta atualizado.'); setPaymentInvoice(null); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao pagar fatura.', 'error'); } };
  return <><PageIntro title="Controle limites, compras, faturas e compromissos futuros sem misturar cartão com saldo bancário." action={<div className="page-actions"><Button onClick={() => setEditingCard(null)}>Novo cartão</Button><Button tone="secondary" onClick={() => setPurchaseOpen(true)} disabled={!cards.some((card) => card.ativo) || categories.length === 0}>Nova compra</Button></div>} /><div className="metric-grid compact"><Metric title="Limite total" value={money(cards.reduce((sum, card) => sum + card.limiteTotalCentavos, 0))} tone="balance" /><Metric title="Limite utilizado" value={money(Object.values(limits).reduce((sum, limit) => sum + limit.limiteUtilizadoCentavos, 0))} tone="expense" /><Metric title="Limite disponível" value={money(Object.values(limits).reduce((sum, limit) => sum + limit.limiteDisponivelCentavos, 0))} tone="income" /></div><Card title="Cartões cadastrados">{cards.length === 0 ? <EmptyState text="Cadastre um cartão para começar a registrar compras no crédito." /> : <div className="table-scroll"><table><thead><tr><th>Cartão</th><th>Limite total</th><th>Utilizado</th><th>Disponível</th><th>Fechamento / vencimento</th><th>Situação</th><th /></tr></thead><tbody>{cards.map((card) => <tr key={card.id}><td><strong>{card.nome}</strong><small>{card.bandeira} · final {card.ultimosDigitos}</small></td><td>{money(card.limiteTotalCentavos)}</td><td>{money(limits[card.id]?.limiteUtilizadoCentavos ?? 0)}<small>{limits[card.id]?.percentualUtilizado ?? 0}% utilizado</small></td><td><strong className="income-text">{money(limits[card.id]?.limiteDisponivelCentavos ?? card.limiteTotalCentavos)}</strong></td><td>Dia {card.diaFechamento} / dia {card.diaVencimento}</td><td><Status active={card.ativo} /></td><td className="actions"><button onClick={() => setEditingCard(card)}>Editar</button><button onClick={async () => { try { await api.cardStatus(card.id, !card.ativo); notify('Situação atualizada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar cartão.', 'error'); } }}>{card.ativo ? 'Desativar' : 'Ativar'}</button></td></tr>)}</tbody></table></div>}</Card><Card title="Faturas">{invoices.length === 0 ? <EmptyState text="As faturas serão criadas automaticamente ao registrar compras." /> : <div className="table-scroll"><table><thead><tr><th>Competência</th><th>Cartão</th><th>Fechamento</th><th>Vencimento</th><th>Valor</th><th>Status</th><th /></tr></thead><tbody>{invoices.map((invoice) => <tr key={invoice.id}><td>{new Intl.DateTimeFormat('pt-BR', { month: 'short', year: 'numeric' }).format(new Date(invoice.competencia))}</td><td>{invoice.cartaoNome}</td><td>{date(invoice.dataFechamento)}</td><td>{date(invoice.dataVencimento)}</td><td><strong>{money(invoice.valorTotalCentavos)}</strong></td><td><span className={`status ${invoice.status.toLowerCase()}`}>{invoiceStatus(invoice.status)}</span></td><td className="actions"><button onClick={async () => { try { setInvoiceDetail(await api.invoice(invoice.id)); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao abrir fatura.', 'error'); } }}>Detalhes</button>{invoice.status === 'ABERTA' && <button onClick={async () => { try { await api.closeInvoice(invoice.id); notify('Fatura fechada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao fechar fatura.', 'error'); } }}>Fechar</button>}{(invoice.status === 'FECHADA' || invoice.status === 'VENCIDA') && <button onClick={() => setPaymentInvoice(invoice)}>Pagar</button>}</td></tr>)}</tbody></table></div>}</Card><Card title="Compras e parcelamentos">{purchases.length === 0 ? <EmptyState text="Nenhuma compra no cartão registrada." /> : <div className="table-scroll"><table><thead><tr><th>Compra</th><th>Cartão</th><th>Categoria</th><th>Parcelas</th><th>Valor</th><th>Status</th><th /></tr></thead><tbody>{purchases.map((purchase) => <tr key={purchase.id}><td><strong>{purchase.descricao}</strong><small>{date(purchase.dataCompra)}</small></td><td>{purchase.cartaoNome}</td><td>{purchase.categoriaNome}</td><td>{purchase.quantidadeParcelas}x · {purchase.parcelas.map((item) => money(item.valorCentavos)).join(' / ')}</td><td>{money(purchase.valorTotalCentavos)}</td><td><span className={`status ${purchase.status.toLowerCase()}`}>{purchase.status}</span></td><td className="actions">{purchase.status === 'ATIVA' && <button onClick={async () => { if (!window.confirm(`Cancelar ${purchase.descricao}?`)) return; try { await api.cancelCardPurchase(purchase.id); notify('Compra cancelada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Use estorno para compras já fechadas.', 'error'); } }}>Cancelar</button>}</td></tr>)}</tbody></table></div>}</Card>{cards.length > 0 && <Card title="Projeção de próximas faturas"><div className="table-scroll"><table><thead><tr><th>Cartão</th><th>Competência</th><th>Comprometido</th><th>Status</th></tr></thead><tbody>{invoices.filter((invoice) => invoice.status !== 'PAGA' && invoice.status !== 'CANCELADA').map((invoice) => <tr key={`projection-${invoice.id}`}><td>{invoice.cartaoNome}</td><td>{new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(new Date(invoice.competencia))}</td><td>{money(invoice.valorTotalCentavos)}</td><td>{invoiceStatus(invoice.status)}</td></tr>)}</tbody></table></div></Card>}{editingCard !== undefined && <CardModal card={editingCard} members={members} accounts={accounts} onClose={() => setEditingCard(undefined)} onSave={saveCard} />}{purchaseOpen && <CardPurchaseModal cards={cards.filter((card) => card.ativo)} members={members} categories={categories} onClose={() => setPurchaseOpen(false)} onSave={savePurchase} />}{paymentInvoice && <InvoicePaymentModal invoice={paymentInvoice} accounts={accounts} onClose={() => setPaymentInvoice(null)} onPay={pay} />}{invoiceDetail && <InvoiceDetailModal detail={invoiceDetail} onClose={() => setInvoiceDetail(null)} />}</>;
}

function CardModal({ card, members, accounts, onClose, onSave }: { card: CreditCard | null; members: Member[]; accounts: Account[]; onClose: () => void; onSave: (payload: CardRequest) => Promise<void> }) { const [nome, setNome] = useState(card?.nome ?? ''); const [membroId, setMembroId] = useState(card?.membroId ?? members[0]?.id ?? ''); const [bandeira, setBandeira] = useState(card?.bandeira ?? 'Visa'); const [digits, setDigits] = useState(card?.ultimosDigitos ?? ''); const [limit, setLimit] = useState(String((card?.limiteTotalCentavos ?? 0) / 100)); const [closing, setClosing] = useState(String(card?.diaFechamento ?? 5)); const [due, setDue] = useState(String(card?.diaVencimento ?? 12)); const [accountId, setAccountId] = useState(card?.contaPagamentoPadraoId ?? accounts[0]?.id ?? ''); const [observacao, setObservacao] = useState(card?.observacao ?? ''); const [busy, setBusy] = useState(false); return <Modal title={card ? 'Editar cartão' : 'Novo cartão'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ membroId, nome, bandeira, ultimosDigitos: digits, limiteTotalCentavos: Math.round(Number(limit.replace(',', '.')) * 100), diaFechamento: Number(closing), diaVencimento: Number(due), contaPagamentoPadraoId: accountId, observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Nome"><input value={nome} onChange={(event) => setNome(event.target.value)} autoFocus /></Field><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Bandeira"><input value={bandeira} onChange={(event) => setBandeira(event.target.value)} /></Field><Field label="Últimos 4 dígitos"><input value={digits} onChange={(event) => setDigits(event.target.value.replace(/\D/g, '').slice(0, 4))} inputMode="numeric" /></Field><Field label="Limite total (R$)"><input value={limit} onChange={(event) => setLimit(event.target.value)} type="number" min="0.01" step="0.01" /></Field><Field label="Fechamento"><input value={closing} onChange={(event) => setClosing(event.target.value)} type="number" min="1" max="31" /></Field><Field label="Vencimento"><input value={due} onChange={(event) => setDue(event.target.value)} type="number" min="1" max="31" /></Field><Field label="Conta padrão de pagamento"><select value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field></div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><p className="form-hint">Compras reduzem apenas o limite. A conta será debitada somente no pagamento da fatura.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || members.length === 0 || accounts.length === 0}>{busy ? 'Salvando…' : 'Salvar cartão'}</Button></div></Form></Modal>; }

function CardPurchaseModal({ cards, members, categories, onClose, onSave }: { cards: CreditCard[]; members: Member[]; categories: Category[]; onClose: () => void; onSave: (payload: CardPurchaseRequest) => Promise<void> }) { const [cardId, setCardId] = useState(cards[0]?.id ?? ''); const [memberId, setMemberId] = useState(members[0]?.id ?? ''); const [categoryId, setCategoryId] = useState(categories[0]?.id ?? ''); const [descricao, setDescricao] = useState(''); const [valor, setValor] = useState(''); const [parcelas, setParcelas] = useState('1'); const [data, setData] = useState(today()); const [observacao, setObservacao] = useState(''); const [busy, setBusy] = useState(false); return <Modal title="Nova compra no cartão" onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ cartaoId: cardId, membroId: memberId, categoriaId: categoryId, descricao, valorTotalCentavos: Math.round(Number(valor.replace(',', '.')) * 100), quantidadeParcelas: Number(parcelas), dataCompra: isoDate(data), observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Cartão"><select value={cardId} onChange={(event) => setCardId(event.target.value)}>{cards.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Membro"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Categoria"><select value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>{categories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Descrição"><input value={descricao} onChange={(event) => setDescricao(event.target.value)} autoFocus /></Field><Field label="Valor (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" /></Field><Field label="Parcelas"><input value={parcelas} onChange={(event) => setParcelas(event.target.value)} type="number" min="1" max="360" /></Field><Field label="Data"><input value={data} onChange={(event) => setData(event.target.value)} type="date" /></Field></div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><p className="form-hint">O valor é distribuído sem perder centavos e cada parcela entra na fatura da competência correta.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || cards.length === 0 || members.length === 0 || categories.length === 0}>{busy ? 'Salvando…' : 'Registrar compra'}</Button></div></Form></Modal>; }

function InvoicePaymentModal({ invoice, accounts, onClose, onPay }: { invoice: Invoice; accounts: Account[]; onClose: () => void; onPay: (invoice: Invoice, accountId: string) => Promise<void> }) { const [accountId, setAccountId] = useState(invoice.contaPagamentoId ?? accounts[0]?.id ?? ''); const [busy, setBusy] = useState(false); return <Modal title={`Pagar fatura · ${invoice.cartaoNome}`} onClose={onClose}><p>Pagamento integral de <strong>{money(invoice.valorTotalCentavos)}</strong>. O débito será lançado na conta selecionada, mas não duplicará o gasto de consumo.</p><Field label="Conta de pagamento"><select value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button disabled={busy || accounts.length === 0} onClick={async () => { setBusy(true); await onPay(invoice, accountId); setBusy(false); }}>{busy ? 'Pagando…' : 'Confirmar pagamento'}</Button></div></Modal>; }

function InvoiceDetailModal({ detail, onClose }: { detail: InvoiceDetail; onClose: () => void }) { return <Modal title={`Fatura ${new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(new Date(detail.fatura.competencia))}`} onClose={onClose}><p><strong>{detail.fatura.cartaoNome}</strong> · fecha em {date(detail.fatura.dataFechamento)} · vence em {date(detail.fatura.dataVencimento)}</p><div className="table-scroll"><table><thead><tr><th>Compra</th><th>Categoria</th><th>Parcela</th><th>Valor</th></tr></thead><tbody>{detail.itens.map((item) => <tr key={item.parcelaId}><td>{item.descricao}</td><td>{item.categoriaNome}</td><td>{item.numeroParcela}/{item.quantidadeTotal}</td><td>{money(item.valorCentavos)}</td></tr>)}</tbody></table></div><div className="statement-summary"><div><span>Total da fatura</span><strong>{money(detail.fatura.valorTotalCentavos)}</strong></div><div><span>Status</span><strong>{invoiceStatus(detail.fatura.status)}</strong></div></div><div className="modal-actions"><Button onClick={onClose}>Fechar</Button></div></Modal>; }

function recurrenceFrequency(value: RecurrenceFrequency) { return ({ DIARIA: 'Diária', SEMANAL: 'Semanal', QUINZENAL: 'Quinzenal', MENSAL: 'Mensal', BIMESTRAL: 'Bimestral', TRIMESTRAL: 'Trimestral', SEMESTRAL: 'Semestral', ANUAL: 'Anual' } as Record<RecurrenceFrequency, string>)[value]; }
function recurrenceStatus(value: RecurrenceStatus) { return ({ ATIVA: 'Ativa', PAUSADA: 'Pausada', ENCERRADA: 'Encerrada' } as Record<RecurrenceStatus, string>)[value]; }
function occurrenceStatus(value: RecurrenceOccurrence['status']) { return ({ PENDENTE: 'Pendente', EFETIVADA: 'Efetivada', IGNORADA: 'Ignorada', ATRASADA: 'Atrasada', CANCELADA: 'Cancelada' } as Record<RecurrenceOccurrence['status'], string>)[value]; }
function periodicity(value: SubscriptionPeriodicity) { return ({ MENSAL: 'Mensal', BIMESTRAL: 'Bimestral', TRIMESTRAL: 'Trimestral', SEMESTRAL: 'Semestral', ANUAL: 'Anual' } as Record<SubscriptionPeriodicity, string>)[value]; }

function RecurrencesPage({ route, notify }: { route: Route; notify: (message: string, kind?: 'success' | 'error') => void }) {
  const [recurrences, setRecurrences] = useState<Recurrence[]>([]); const [occurrences, setOccurrences] = useState<RecurrenceOccurrence[]>([]); const [subscriptions, setSubscriptions] = useState<Subscription[]>([]); const [summary, setSummary] = useState<{ receitasMensaisCentavos: number; despesasMensaisCentavos: number; saldoMensalCentavos: number; saldoRealCentavos: number; saldoProjetadoCentavos: number } | null>(null); const [subscriptionSummary, setSubscriptionSummary] = useState<{ custoMensalCentavos: number; custoAnualCentavos: number; assinaturasAtivas: number } | null>(null);
  const [members, setMembers] = useState<Member[]>([]); const [accounts, setAccounts] = useState<Account[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [cards, setCards] = useState<CreditCard[]>([]); const [editing, setEditing] = useState<Recurrence | null | undefined>(undefined); const [editingSubscription, setEditingSubscription] = useState<Subscription | null | undefined>(undefined); const [effecting, setEffecting] = useState<RecurrenceOccurrence | null>(null); const [editingOccurrence, setEditingOccurrence] = useState<RecurrenceOccurrence | null>(null);
  const load = async () => { try { const [recurrenceList, occurrenceList, subscriptionList, recurrenceData, subscriptionData, people, accountList, categoryList, cardList] = await Promise.all([api.recurrences(), api.upcomingRecurrences(90), api.subscriptions(), api.recurrenceSummary(), api.subscriptionSummary(), api.members(), api.accounts(), api.categories(), api.cards()]); setRecurrences(recurrenceList); setOccurrences(occurrenceList); setSubscriptions(subscriptionList); setSummary(recurrenceData); setSubscriptionSummary(subscriptionData); setMembers(people.filter((item) => item.ativo)); setAccounts(accountList.filter((item) => item.ativo)); setCategories(categoryList.filter((item) => item.ativo)); setCards(cardList.filter((item) => item.ativo)); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao carregar recorrências.', 'error'); } };
  useEffect(() => { void load(); }, []);
  const scope = route.split('/').at(-1) ?? ''; const shownRecurrences = recurrences.filter((item) => scope === 'income' ? item.tipo === 'RECEITA' : scope === 'expenses' ? item.tipo === 'DESPESA' && item.classificacao !== 'CONTA_FIXA' : scope === 'fixed-bills' ? item.classificacao === 'CONTA_FIXA' : true);
  const showSubscriptions = route.includes('subscriptions'); const showUpcoming = route.endsWith('upcoming');
  const saveRecurrence = async (payload: RecurrenceRequest) => { try { if (editing?.id) await api.updateRecurrence(editing.id, payload); else await api.createRecurrence(payload); notify(editing?.id ? 'Recorrência atualizada; o histórico efetivado foi preservado.' : 'Recorrência cadastrada e previsões criadas.'); setEditing(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar recorrência.', 'error'); } };
  const saveSubscription = async (payload: SubscriptionRequest) => { try { if (editingSubscription?.id) await api.updateSubscription(editingSubscription.id, payload); else await api.createSubscription(payload); notify(editingSubscription?.id ? 'Assinatura atualizada.' : 'Assinatura cadastrada.'); setEditingSubscription(undefined); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar assinatura.', 'error'); } };
  return <><PageIntro title={showSubscriptions ? 'Controle assinaturas, cobranças em conta ou cartão e o custo normalizado.' : showUpcoming ? 'Previsões não alteram o saldo. Efetive somente quando a movimentação acontecer.' : 'Planeje receitas, despesas e contas fixas com geração automática de previsões.'} action={<div className="page-actions"><Button onClick={() => setEditing(null)}>Nova recorrência</Button><Button tone="secondary" onClick={() => setEditingSubscription(null)}>Nova assinatura</Button></div>} />
    <div className="metric-grid compact"><Metric title="Receitas mensais" value={money(summary?.receitasMensaisCentavos ?? 0)} tone="income" /><Metric title="Despesas mensais" value={money(summary?.despesasMensaisCentavos ?? 0)} tone="expense" /><Metric title="Saldo mensal projetado" value={money(summary?.saldoMensalCentavos ?? 0)} tone="result" /></div>
    {showSubscriptions ? <><div className="metric-grid compact"><Metric title="Assinaturas ativas" value={String(subscriptionSummary?.assinaturasAtivas ?? 0)} tone="balance" /><Metric title="Custo mensal equivalente" value={money(subscriptionSummary?.custoMensalCentavos ?? 0)} tone="expense" /><Metric title="Custo anual equivalente" value={money(subscriptionSummary?.custoAnualCentavos ?? 0)} tone="expense" /></div><Card title="Assinaturas e serviços"><SubscriptionTable subscriptions={subscriptions} onEdit={setEditingSubscription} onStatus={async (item) => { try { await api.subscriptionStatus(item.id, !item.ativa); notify(item.ativa ? 'Assinatura cancelada; o histórico foi preservado.' : 'Assinatura reativada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar assinatura.', 'error'); } }} /></Card></> : showUpcoming ? <Card title="Próximos 90 dias"><OccurrenceTable occurrences={occurrences} onEffect={setEffecting} onEdit={setEditingOccurrence} onIgnore={async (item) => { try { await api.ignoreOccurrence(item.id); notify('Ocorrência ignorada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao ignorar ocorrência.', 'error'); } }} /></Card> : <><Card title={scope === 'fixed-bills' ? 'Contas fixas' : scope === 'income' ? 'Receitas recorrentes' : scope === 'expenses' ? 'Despesas recorrentes' : 'Recorrências configuradas'}><RecurrenceTable recurrences={shownRecurrences} onEdit={setEditing} onStatus={async (item) => { try { if (item.status === 'ATIVA') await api.pauseRecurrence(item.id); else if (item.status === 'PAUSADA') await api.reactivateRecurrence(item.id); else return; notify(item.status === 'ATIVA' ? 'Recorrência pausada.' : 'Recorrência reativada e previsões atualizadas.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar recorrência.', 'error'); } }} onClose={async (item) => { if (!window.confirm(`Encerrar ${item.descricao}? As previsões já efetivadas serão mantidas.`)) return; try { await api.closeRecurrence(item.id, isoDate(today())); notify('Recorrência encerrada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao encerrar recorrência.', 'error'); } }} /></Card><Card title="Próximos vencimentos"><OccurrenceTable occurrences={occurrences.slice(0, 8)} onEffect={setEffecting} onEdit={setEditingOccurrence} onIgnore={async (item) => { try { await api.ignoreOccurrence(item.id); notify('Ocorrência ignorada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao ignorar ocorrência.', 'error'); } }} /></Card></>}
    {editing !== undefined && <RecurrenceModal recurrence={editing} members={members} accounts={accounts} categories={categories} onClose={() => setEditing(undefined)} onSave={saveRecurrence} />}{editingSubscription !== undefined && <SubscriptionModal subscription={editingSubscription} members={members} accounts={accounts} categories={categories.filter((item) => item.tipo === 'Despesa')} cards={cards} onClose={() => setEditingSubscription(undefined)} onSave={saveSubscription} />}{effecting && <EffectOccurrenceModal occurrence={effecting} onClose={() => setEffecting(null)} onSave={async (payload) => { try { await api.effectOccurrence(effecting.id, payload); notify('Ocorrência efetivada e movimentação real criada.'); setEffecting(null); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao efetivar ocorrência.', 'error'); } }} />}{editingOccurrence && <OccurrenceModal occurrence={editingOccurrence} onClose={() => setEditingOccurrence(null)} onSave={async (payload) => { try { await api.updateOccurrence(editingOccurrence.id, payload); notify('Exceção da ocorrência atualizada.'); setEditingOccurrence(null); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar ocorrência.', 'error'); } }} />}</>;
}

function RecurrenceTable({ recurrences, onEdit, onStatus, onClose }: { recurrences: Recurrence[]; onEdit: (item: Recurrence) => void; onStatus: (item: Recurrence) => Promise<void>; onClose: (item: Recurrence) => Promise<void> }) { return recurrences.length === 0 ? <EmptyState text="Nenhuma recorrência configurada neste recorte." /> : <div className="table-scroll"><table><thead><tr><th>Descrição</th><th>Tipo</th><th>Valor / frequência</th><th>Próxima ocorrência</th><th>Situação</th><th /></tr></thead><tbody>{recurrences.map((item) => <tr key={item.id}><td><strong>{item.descricao}</strong><small>{item.membroNome} · {item.contaNome} · {item.categoriaNome}{item.classificacao === 'CONTA_FIXA' ? ' · Conta fixa' : ''}</small></td><td><span className={`type-tag ${item.tipo === 'RECEITA' ? 'income' : 'expense'}`}>{item.tipo === 'RECEITA' ? 'Receita' : 'Despesa'}</span></td><td><strong className={item.tipo === 'RECEITA' ? 'income-text' : 'expense-text'}>{money(item.valorCentavos)}</strong><small>{recurrenceFrequency(item.frequencia)}{item.valorVariavel ? ' · variável' : ''}</small></td><td>{date(item.proximaOcorrencia)}</td><td><span className={`status ${item.status.toLowerCase()}`}>{recurrenceStatus(item.status)}</span></td><td className="actions"><button onClick={() => onEdit(item)}>Editar</button>{item.status !== 'ENCERRADA' && <button onClick={() => void onStatus(item)}>{item.status === 'ATIVA' ? 'Pausar' : 'Reativar'}</button>}{item.status !== 'ENCERRADA' && <button onClick={() => void onClose(item)}>Encerrar</button>}</td></tr>)}</tbody></table></div>; }
function OccurrenceTable({ occurrences, onEffect, onEdit, onIgnore }: { occurrences: RecurrenceOccurrence[]; onEffect: (item: RecurrenceOccurrence) => void; onEdit: (item: RecurrenceOccurrence) => void; onIgnore: (item: RecurrenceOccurrence) => Promise<void> }) { return occurrences.length === 0 ? <EmptyState text="Não há ocorrências previstas para o período." /> : <div className="table-scroll"><table><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Previsto</th><th>Status</th><th /></tr></thead><tbody>{occurrences.map((item) => <tr key={item.id}><td>{date(item.dataPrevista)}</td><td><strong>{item.descricao}</strong><small>{item.classificacao === 'CONTA_FIXA' ? 'Conta fixa' : 'Recorrência'}</small></td><td><span className={`type-tag ${item.tipo === 'RECEITA' ? 'income' : 'expense'}`}>{item.tipo === 'RECEITA' ? 'Receita' : 'Despesa'}</span></td><td className={item.tipo === 'RECEITA' ? 'income-text' : 'expense-text'}>{money(item.valorRealizadoCentavos ?? item.valorPrevistoCentavos)}</td><td><span className={`status ${item.status.toLowerCase()}`}>{occurrenceStatus(item.status)}</span></td><td className="actions">{(item.status === 'PENDENTE' || item.status === 'ATRASADA') && <><button onClick={() => onEffect(item)}>Efetivar</button><button onClick={() => onEdit(item)}>Exceção</button><button onClick={() => void onIgnore(item)}>Ignorar</button></>}</td></tr>)}</tbody></table></div>; }
function SubscriptionTable({ subscriptions, onEdit, onStatus }: { subscriptions: Subscription[]; onEdit: (item: Subscription) => void; onStatus: (item: Subscription) => Promise<void> }) { return subscriptions.length === 0 ? <EmptyState text="Cadastre uma assinatura para acompanhar custos recorrentes." /> : <div className="table-scroll"><table><thead><tr><th>Serviço</th><th>Cobrança</th><th>Periodicidade</th><th>Equivalente mensal</th><th>Próxima cobrança</th><th>Situação</th><th /></tr></thead><tbody>{subscriptions.map((item) => <tr key={item.id}><td><strong>{item.nome}</strong><small>{item.membroNome} · {item.categoriaNome}</small></td><td>{item.metodoPagamento === 'CARTAO' ? `Cartão · ${item.cartaoNome ?? 'não informado'}` : `Conta · ${item.contaNome}`}</td><td>{periodicity(item.periodicidade)} · {money(item.valorCentavos)}</td><td className="expense-text">{money(item.custoMensalEquivalenteCentavos)}</td><td>{date(item.proximaCobranca)}</td><td><Status active={item.ativa} /></td><td className="actions"><button onClick={() => onEdit(item)}>Editar</button><button onClick={() => void onStatus(item)}>{item.ativa ? 'Cancelar' : 'Reativar'}</button></td></tr>)}</tbody></table></div>; }

function RecurrenceModal({ recurrence, members, accounts, categories, onClose, onSave }: { recurrence: Recurrence | null; members: Member[]; accounts: Account[]; categories: Category[]; onClose: () => void; onSave: (payload: RecurrenceRequest) => Promise<void> }) { const [membroId, setMembroId] = useState(recurrence?.membroId ?? members[0]?.id ?? ''); const [contaId, setContaId] = useState(recurrence?.contaId ?? accounts[0]?.id ?? ''); const [tipo, setTipo] = useState<TransactionType>(recurrence?.tipo ?? 'DESPESA'); const [categoriaId, setCategoriaId] = useState(recurrence?.categoriaId ?? categories.find((item) => item.tipo === 'Despesa')?.id ?? ''); const [descricao, setDescricao] = useState(recurrence?.descricao ?? ''); const [valor, setValor] = useState(String((recurrence?.valorCentavos ?? 0) / 100)); const [frequencia, setFrequencia] = useState<RecurrenceFrequency>(recurrence?.frequencia ?? 'MENSAL'); const [inicio, setInicio] = useState(recurrence ? recurrence.dataInicio.slice(0, 10) : today()); const [fim, setFim] = useState(recurrence?.dataFim?.slice(0, 10) ?? ''); const [contaFixa, setContaFixa] = useState(recurrence?.classificacao === 'CONTA_FIXA'); const [variavel, setVariavel] = useState(recurrence?.valorVariavel ?? false); const [automatico, setAutomatico] = useState(recurrence?.gerarAutomaticamente ?? true); const [observacao, setObservacao] = useState(recurrence?.observacao ?? ''); const [busy, setBusy] = useState(false); const filteredCategories = categories.filter((item) => item.tipo === (tipo === 'RECEITA' ? 'Receita' : 'Despesa'));
  return <Modal title={recurrence ? 'Editar recorrência' : 'Nova recorrência'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ membroId, contaId, categoriaId, tipo, descricao, valorCentavos: Math.round(Number(valor.replace(',', '.')) * 100), frequencia, dataInicio: isoDate(inicio), dataFim: fim ? isoDate(fim) : undefined, gerarAutomaticamente: automatico, valorVariavel: variavel, classificacao: contaFixa ? 'CONTA_FIXA' : 'NORMAL', observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Conta"><select value={contaId} onChange={(event) => setContaId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Tipo"><select value={tipo} onChange={(event) => { const nextType = event.target.value as TransactionType; setTipo(nextType); setCategoriaId(categories.find((item) => item.tipo === (nextType === 'RECEITA' ? 'Receita' : 'Despesa'))?.id ?? ''); }}><option value="RECEITA">Receita</option><option value="DESPESA">Despesa</option></select></Field><Field label="Categoria"><select value={categoriaId} onChange={(event) => setCategoriaId(event.target.value)}>{filteredCategories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Descrição"><input value={descricao} onChange={(event) => setDescricao(event.target.value)} autoFocus /></Field><Field label="Valor previsto (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" /></Field><Field label="Frequência"><select value={frequencia} onChange={(event) => setFrequencia(event.target.value as RecurrenceFrequency)}>{(['DIARIA', 'SEMANAL', 'QUINZENAL', 'MENSAL', 'BIMESTRAL', 'TRIMESTRAL', 'SEMESTRAL', 'ANUAL'] as RecurrenceFrequency[]).map((item) => <option key={item} value={item}>{recurrenceFrequency(item)}</option>)}</select></Field><Field label="Data de início"><input type="date" value={inicio} onChange={(event) => setInicio(event.target.value)} /></Field><Field label="Data final (opcional)"><input type="date" value={fim} onChange={(event) => setFim(event.target.value)} /></Field></div><div className="toggle-row"><label><input type="checkbox" checked={automatico} onChange={(event) => setAutomatico(event.target.checked)} /> Gerar previsões automaticamente</label><label><input type="checkbox" checked={contaFixa} onChange={(event) => setContaFixa(event.target.checked)} /> Classificar como conta fixa</label><label><input type="checkbox" checked={variavel} onChange={(event) => setVariavel(event.target.checked)} /> Valor variável</label></div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><p className="form-hint">A previsão não altera o saldo. Somente a efetivação cria uma movimentação real.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || !membroId || !contaId || !categoriaId}>{busy ? 'Salvando…' : 'Salvar recorrência'}</Button></div></Form></Modal>; }
function SubscriptionModal({ subscription, members, accounts, categories, cards, onClose, onSave }: { subscription: Subscription | null; members: Member[]; accounts: Account[]; categories: Category[]; cards: CreditCard[]; onClose: () => void; onSave: (payload: SubscriptionRequest) => Promise<void> }) { const [membroId, setMembroId] = useState(subscription?.membroId ?? members[0]?.id ?? ''); const [nome, setNome] = useState(subscription?.nome ?? ''); const [categoriaId, setCategoriaId] = useState(subscription?.categoriaId ?? categories[0]?.id ?? ''); const [contaId, setContaId] = useState(subscription?.contaId ?? accounts[0]?.id ?? ''); const [valor, setValor] = useState(String((subscription?.valorCentavos ?? 0) / 100)); const [periodicidade, setPeriodicidade] = useState<SubscriptionPeriodicity>(subscription?.periodicidade ?? 'MENSAL'); const [inicio, setInicio] = useState(subscription ? subscription.dataInicio.slice(0, 10) : today()); const [proxima, setProxima] = useState(subscription ? subscription.proximaCobranca.slice(0, 10) : today()); const [metodo, setMetodo] = useState<SubscriptionPaymentMethod>(subscription?.metodoPagamento ?? 'CONTA'); const [cartaoId, setCartaoId] = useState(subscription?.cartaoId ?? cards[0]?.id ?? ''); const [observacao, setObservacao] = useState(subscription?.observacao ?? ''); const [busy, setBusy] = useState(false);
  return <Modal title={subscription ? 'Editar assinatura' : 'Nova assinatura'} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ membroId, nome, categoriaId, contaId, valorCentavos: Math.round(Number(valor.replace(',', '.')) * 100), periodicidade, dataInicio: isoDate(inicio), proximaCobranca: isoDate(proxima), metodoPagamento: metodo, cartaoId: metodo === 'CARTAO' ? cartaoId : undefined, observacao: observacao || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Serviço"><input value={nome} onChange={(event) => setNome(event.target.value)} autoFocus /></Field><Field label="Membro"><select value={membroId} onChange={(event) => setMembroId(event.target.value)}>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Categoria"><select value={categoriaId} onChange={(event) => setCategoriaId(event.target.value)}>{categories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Conta"><select value={contaId} onChange={(event) => setContaId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Valor (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" /></Field><Field label="Periodicidade"><select value={periodicidade} onChange={(event) => setPeriodicidade(event.target.value as SubscriptionPeriodicity)}>{(['MENSAL', 'BIMESTRAL', 'TRIMESTRAL', 'SEMESTRAL', 'ANUAL'] as SubscriptionPeriodicity[]).map((item) => <option key={item} value={item}>{periodicity(item)}</option>)}</select></Field><Field label="Início"><input type="date" value={inicio} onChange={(event) => setInicio(event.target.value)} /></Field><Field label="Próxima cobrança"><input type="date" value={proxima} onChange={(event) => setProxima(event.target.value)} /></Field><Field label="Cobrar por"><select value={metodo} onChange={(event) => setMetodo(event.target.value as SubscriptionPaymentMethod)}><option value="CONTA">Conta bancária</option><option value="CARTAO">Cartão de crédito</option></select></Field>{metodo === 'CARTAO' && <Field label="Cartão"><select value={cartaoId} onChange={(event) => setCartaoId(event.target.value)}>{cards.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field>}</div><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><p className="form-hint">Conta gera despesa prevista; cartão gera compra de uma parcela na fatura correspondente.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || !membroId || !contaId || !categoriaId || (metodo === 'CARTAO' && !cartaoId)}>{busy ? 'Salvando…' : 'Salvar assinatura'}</Button></div></Form></Modal>; }
function EffectOccurrenceModal({ occurrence, onClose, onSave }: { occurrence: RecurrenceOccurrence; onClose: () => void; onSave: (payload: { valorRealizadoCentavos: number; dataEfetivacao?: string; observacao?: string }) => Promise<void> }) { const [valor, setValor] = useState(String(occurrence.valorPrevistoCentavos / 100)); const [dataEfetivacao, setDataEfetivacao] = useState(occurrence.dataPrevista.slice(0, 10)); const [observacao, setObservacao] = useState(occurrence.observacao ?? ''); const [busy, setBusy] = useState(false); return <Modal title={`Efetivar · ${occurrence.descricao}`} onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ valorRealizadoCentavos: Math.round(Number(valor.replace(',', '.')) * 100), dataEfetivacao: isoDate(dataEfetivacao), observacao: observacao || undefined }); setBusy(false); }}><Field label="Valor realizado (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" autoFocus /></Field><Field label="Data de efetivação"><input type="date" value={dataEfetivacao} onChange={(event) => setDataEfetivacao(event.target.value)} /></Field><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><p className="form-hint">Uma movimentação efetivada será criada na conta da recorrência.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy}>{busy ? 'Efetivando…' : 'Confirmar efetivação'}</Button></div></Form></Modal>; }
function OccurrenceModal({ occurrence, onClose, onSave }: { occurrence: RecurrenceOccurrence; onClose: () => void; onSave: (payload: { valorPrevistoCentavos: number; dataPrevista?: string; observacao?: string }) => Promise<void> }) { const [valor, setValor] = useState(String(occurrence.valorPrevistoCentavos / 100)); const [dataPrevista, setDataPrevista] = useState(occurrence.dataPrevista.slice(0, 10)); const [observacao, setObservacao] = useState(occurrence.observacao ?? ''); const [busy, setBusy] = useState(false); return <Modal title="Exceção de ocorrência" onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ valorPrevistoCentavos: Math.round(Number(valor.replace(',', '.')) * 100), dataPrevista: isoDate(dataPrevista), observacao: observacao || undefined }); setBusy(false); }}><Field label="Valor previsto (R$)"><input value={valor} onChange={(event) => setValor(event.target.value)} type="number" min="0.01" step="0.01" autoFocus /></Field><Field label="Nova data"><input type="date" value={dataPrevista} onChange={(event) => setDataPrevista(event.target.value)} /></Field><Field label="Observação"><textarea value={observacao} onChange={(event) => setObservacao(event.target.value)} rows={2} /></Field><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy}>{busy ? 'Salvando…' : 'Salvar exceção'}</Button></div></Form></Modal>; }

function FamilyAdminPage({ route, notify }: { route: Route; notify: (message: string, kind?: ToastKind) => void }) {
  const [family, setFamily] = useState<Family | null>(null); const [members, setMembers] = useState<Member[]>([]); const [users, setUsers] = useState<ManagedUser[]>([]); const [profiles, setProfiles] = useState<FinancialProfile[]>([]); const [busy, setBusy] = useState(false); const [memberName, setMemberName] = useState(''); const [memberType, setMemberType] = useState('TITULAR'); const [login, setLogin] = useState(''); const [password, setPassword] = useState(''); const [userMember, setUserMember] = useState(''); const [userProfile, setUserProfile] = useState('MEMBRO');
  const load = async () => { try { const [nextFamily, nextMembers, nextUsers, nextProfiles] = await Promise.all([api.family(), api.members(), api.users(), api.financialProfiles()]); setFamily(nextFamily); setMembers(nextMembers); setUsers(nextUsers); setProfiles(nextProfiles); if (!userMember) setUserMember(nextMembers.find((item) => !item.possuiUsuario && item.ativo)?.id ?? ''); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível carregar a administração da família.', 'error'); } };
  useEffect(() => { void load(); }, [route]);
  const createMember = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { await api.createMember({ nome: memberName, tipo: memberType as Member['tipo'] }); setMemberName(''); notify('Membro cadastrado; histórico financeiro será preservado.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao cadastrar membro.', 'error'); } finally { setBusy(false); } };
  const createUser = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { await api.createUser({ membroId: userMember, login, senha: password, perfil: userProfile }); setLogin(''); setPassword(''); notify('Acesso local criado para o membro.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao criar acesso.', 'error'); } finally { setBusy(false); } };
  const title = route === 'family/permissions' ? 'Permissões por perfil e escopo de dados.' : route === 'family/invitations' ? 'Convites locais: crie um login independente para um membro.' : route === 'family/financial-profile' ? 'Consolidação financeira por membro, sem criar lançamentos.' : route === 'family/expense-split' ? 'Rateios definem responsabilidade sem duplicar a despesa familiar.' : 'Família, membros e acessos locais.';
  return <><PageIntro title={title} /><div className="metric-grid compact"><Metric title="Membros ativos" value={String(members.filter((item) => item.ativo).length)} tone="balance" /><Metric title="Usuários locais" value={String(users.filter((item) => item.ativo).length)} tone="income" /><Metric title="Família" value={family?.nome ?? '…'} tone="result" /></div>{route === 'family/financial-profile' ? <Card title="Perfil financeiro por membro"><div className="table-scroll"><table><thead><tr><th>Membro</th><th>Contas</th><th>Receitas do mês</th><th>Despesas do mês</th><th>Cartão</th><th>Orçamento</th></tr></thead><tbody>{profiles.map((item) => <tr key={item.membroId}><td><strong>{item.membroNome}</strong></td><td>{money(item.contasCentavos)}</td><td className="income-text">{money(item.receitasMesCentavos)}</td><td className="expense-text">{money(item.despesasMesCentavos)}</td><td>{money(item.cartaoCentavos)}</td><td>{item.orcamentoUtilizadoPercentual.toLocaleString('pt-BR')}%</td></tr>)}</tbody></table></div></Card> : route === 'family/invitations' ? <div className="settings-grid"><Card title="Criar acesso local"><Form onSubmit={createUser}><Field label="Membro"><select value={userMember} onChange={(event) => setUserMember(event.target.value)}>{members.filter((item) => item.ativo && !item.possuiUsuario).map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Login"><input value={login} onChange={(event) => setLogin(event.target.value)} placeholder="ex.: luar" /></Field><Field label="Senha temporária"><input value={password} onChange={(event) => setPassword(event.target.value)} minLength={8} type="password" placeholder="mínimo de 8 caracteres" /></Field><Field label="Perfil"><select value={userProfile} onChange={(event) => setUserProfile(event.target.value)}><option value="MEMBRO">Membro</option><option value="SOMENTE_LEITURA">Somente leitura</option><option value="ADMINISTRADOR">Administrador</option></select></Field><Button type="submit" disabled={busy || !userMember}>{busy ? 'Criando…' : 'Criar acesso'}</Button></Form></Card><Card title="Acessos existentes"><UserTable users={users} onStatus={async (item) => { try { await api.userStatus(item.id, !item.ativo); notify('Situação do acesso atualizada.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao atualizar usuário.', 'error'); } }} /></Card></div> : route === 'family/permissions' ? <div className="settings-grid"><Card title="Perfis padrão"><ul className="check-list"><li>Administrador · família inteira + administração</li><li>Membro · consulta e operação conforme o módulo</li><li>Somente leitura · consulta e relatórios, sem escrita</li><li>Escopo de dados preparado para próprios, família e selecionados</li></ul></Card><Card title="Usuários e perfil aplicado"><UserTable users={users} onStatus={async () => undefined} /></Card></div> : route === 'family/expense-split' ? <ExpenseSplitPanel members={members.filter((item) => item.ativo)} notify={notify} /> : <div className="settings-grid"><Card title="Novo membro"><Form onSubmit={createMember}><Field label="Nome"><input value={memberName} onChange={(event) => setMemberName(event.target.value)} placeholder="Ex.: Filho" /></Field><Field label="Tipo"><select value={memberType} onChange={(event) => setMemberType(event.target.value)}><option value="TITULAR">Titular</option><option value="CONJUGE">Cônjuge</option><option value="DEPENDENTE">Dependente</option><option value="OUTRO">Outro</option></select></Field><Button type="submit" disabled={busy || !memberName.trim()}>Adicionar membro</Button></Form></Card><Card title="Membros cadastrados"><div className="table-scroll"><table><thead><tr><th>Nome</th><th>Tipo</th><th>Acesso</th><th>Situação</th></tr></thead><tbody>{members.map((item) => <tr key={item.id}><td><strong>{item.nome}</strong><small>{item.descricao || 'Sem observação'}</small></td><td>{item.tipo ?? 'TITULAR'}</td><td>{item.possuiUsuario ? 'Login independente' : 'Sem acesso'}</td><td><Status active={item.ativo} /></td></tr>)}</tbody></table></div></Card></div>}</>;
}

function UserTable({ users, onStatus }: { users: ManagedUser[]; onStatus: (user: ManagedUser) => Promise<void> }) { return <div className="table-scroll"><table><thead><tr><th>Usuário</th><th>Membro</th><th>Perfil</th><th>Situação</th><th /></tr></thead><tbody>{users.map((item) => <tr key={item.id}><td><strong>{item.login}</strong><small>{item.nome}</small></td><td>{item.membroNome || '—'}</td><td>{item.perfil}</td><td><Status active={item.ativo} /></td><td className="actions"><button onClick={() => void onStatus(item)}>{item.ativo ? 'Desativar' : 'Ativar'}</button></td></tr>)}</tbody></table></div>; }

function ExpenseSplitPanel({ members, notify }: { members: Member[]; notify: (message: string, kind?: ToastKind) => void }) { const [transactions, setTransactions] = useState<Transaction[]>([]); const [selected, setSelected] = useState(''); const [type, setType] = useState<'PERCENTUAL' | 'VALOR_FIXO' | 'IGUALITARIO'>('PERCENTUAL'); const [values, setValues] = useState<Record<string, string>>({}); const [split, setSplit] = useState<any>(null); useEffect(() => { void api.transactions({ tipo: 'DESPESA', tamanhoPagina: 100 }).then((result) => { setTransactions(result.items); setSelected(result.items[0]?.id ?? ''); }).catch((error) => notify(error instanceof Error ? error.message : 'Erro ao carregar despesas.', 'error')); }, []); const current = transactions.find((item) => item.id === selected); const save = async () => { if (!current) return; try { const itens = members.map((member) => ({ membroId: member.id, percentual: type === 'PERCENTUAL' ? Number(values[member.id] || 0) : 0, valorCentavos: type === 'VALOR_FIXO' ? Math.round(Number(values[member.id] || 0) * 100) : 0 })).filter((item) => type === 'IGUALITARIO' || item.percentual > 0 || item.valorCentavos > 0); const result = await api.saveSplit(current.id, { tipo: type, itens }); setSplit(result); notify('Rateio salvo; a despesa original continua única.'); } catch (error) { notify(error instanceof Error ? error.message : 'Rateio inválido.', 'error'); } }; return <div className="settings-grid"><Card title="Configurar rateio"><Field label="Despesa"><select value={selected} onChange={async (event) => { setSelected(event.target.value); setSplit(await api.split(event.target.value)); }}>{transactions.map((item) => <option key={item.id} value={item.id}>{item.descricao} · {money(item.valorCentavos)}</option>)}</select></Field><Field label="Forma"><select value={type} onChange={(event) => setType(event.target.value as typeof type)}><option value="PERCENTUAL">Percentual</option><option value="VALOR_FIXO">Valor fixo</option><option value="IGUALITARIO">Igualitário</option></select></Field>{type !== 'IGUALITARIO' && members.map((member) => <Field key={member.id} label={member.nome}><input type="number" step="0.01" value={values[member.id] ?? ''} onChange={(event) => setValues((currentValues) => ({ ...currentValues, [member.id]: event.target.value }))} placeholder={type === 'PERCENTUAL' ? '0%' : 'R$ 0,00'} /></Field>)}<Button onClick={() => void save()} disabled={!current}>Validar e salvar rateio</Button></Card><Card title="Rateio aplicado"><p>O valor da despesa permanece {current ? money(current.valorCentavos) : '—'} no consolidado familiar.</p>{split ? <table><thead><tr><th>Membro</th><th>Percentual</th><th>Responsabilidade</th></tr></thead><tbody>{split.itens.map((item: { membroNome: string; percentual: number; valorCentavos: number }) => <tr key={item.membroNome}><td>{item.membroNome}</td><td>{item.percentual.toLocaleString('pt-BR')}%</td><td>{money(item.valorCentavos)}</td></tr>)}</tbody></table> : <EmptyState text="Nenhum rateio aplicado nesta despesa." />}</Card></div>; }

function Sprint7SettingsPage({ route, notify }: { route: Route; notify: (message: string, kind?: ToastKind) => void }) { const [info, setInfo] = useState<SystemHealth | null>(null); const [settings, setSettings] = useState<FamilySettings | null>(null); const [preferences, setPreferences] = useState<UserPreferences | null>(null); const [notifications, setNotifications] = useState<NotificationSettings | null>(null); const [backup, setBackup] = useState(false); const [passwords, setPasswords] = useState({ senhaAtual: '', novaSenha: '' }); useEffect(() => { void Promise.all([api.system(), api.settings(), api.preferences(), api.notifications()]).then(([health, nextSettings, nextPreferences, nextNotifications]) => { setInfo(health); setSettings(nextSettings); setPreferences(nextPreferences); setNotifications(nextNotifications); }).catch((error) => notify(error instanceof Error ? error.message : 'Erro ao carregar configurações.', 'error')); }, [route]); const saveFamily = async () => { if (!settings) return; try { const result = await api.updateSettingsFamily({ nome: settings.familia.nome, moedaPadrao: settings.familia.moedaPadrao, timezone: settings.familia.timezone }); setSettings(result); notify('Configuração da família atualizada.'); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar família.', 'error'); } }; const savePreferences = async () => { if (!preferences) return; try { setPreferences(await api.updatePreferences(preferences)); notify('Preferências salvas para este usuário.'); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar preferências.', 'error'); } }; const saveNotifications = async () => { if (!notifications) return; try { setNotifications(await api.updateNotifications(notifications)); notify('Notificações atualizadas.'); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar notificações.', 'error'); } };
  return <><PageIntro title={route === 'settings/security' ? 'Senha local, bloqueio e proteção da sessão.' : route === 'settings/preferences' ? 'Preferências individuais que não alteram os demais membros.' : 'Parâmetros de família, integridade, backup e operação offline.'} /><div className="settings-grid">{(route === 'settings' || route === 'settings/appearance') && <Card title="Sistema e integridade"><dl><div><dt>Versão</dt><dd>{info?.version ?? '…'}</dd></div><div><dt>Schema</dt><dd>{info?.schema ?? '…'}</dd></div><div><dt>Banco</dt><dd>{info?.database ?? '…'}</dd></div><div><dt>Integridade</dt><dd>{info?.integrityOk ? 'OK' : info?.integrityMessage ?? '…'}</dd></div><div><dt>Modo</dt><dd>Local / Offline</dd></div></dl><Button disabled={backup} onClick={async () => { setBackup(true); try { const result = await api.backup(); notify(`Backup criado: ${result.nomeArquivo}`); setInfo(await api.system()); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao gerar backup.', 'error'); } finally { setBackup(false); } }}>{backup ? 'Criando backup…' : 'Criar backup versionado'}</Button></Card>}{(route === 'settings' || route === 'settings/preferences') && preferences && <Card title="Preferências do usuário"><Field label="Página inicial"><input value={preferences.paginaInicial} onChange={(event) => setPreferences({ ...preferences, paginaInicial: event.target.value })} /></Field><Field label="Tema"><select value={preferences.tema} onChange={(event) => setPreferences({ ...preferences, tema: event.target.value })}><option value="sistema">Sistema</option><option value="claro">Claro</option><option value="escuro">Escuro</option></select></Field><Field label="Itens por página"><input type="number" min="5" max="100" value={preferences.itensPorPagina} onChange={(event) => setPreferences({ ...preferences, itensPorPagina: Number(event.target.value) })} /></Field><Button onClick={() => void savePreferences()}>Salvar preferências</Button></Card>}{route === 'settings/security' && <Card title="Alterar senha local"><Field label="Senha atual"><input type="password" value={passwords.senhaAtual} onChange={(event) => setPasswords({ ...passwords, senhaAtual: event.target.value })} /></Field><Field label="Nova senha"><input type="password" minLength={8} value={passwords.novaSenha} onChange={(event) => setPasswords({ ...passwords, novaSenha: event.target.value })} /></Field><Button onClick={async () => { try { await api.changePassword(passwords); notify('Senha alterada.'); setPasswords({ senhaAtual: '', novaSenha: '' }); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao alterar senha.', 'error'); } }}>Alterar senha</Button><Button tone="secondary" onClick={async () => { await api.lock(); setSession(''); window.location.hash = '/dashboard'; window.location.reload(); }}>Bloquear aplicação</Button></Card>}{(route === 'settings' || route === 'settings/notifications') && notifications && <Card title="Notificações"><label className="toggle-row"><input type="checkbox" checked={notifications.avisarContasProximas} onChange={(event) => setNotifications({ ...notifications, avisarContasProximas: event.target.checked })} /> Contas próximas</label><label className="toggle-row"><input type="checkbox" checked={notifications.avisarFatura} onChange={(event) => setNotifications({ ...notifications, avisarFatura: event.target.checked })} /> Faturas</label><label className="toggle-row"><input type="checkbox" checked={notifications.avisarSaldoProjetadoNegativo} onChange={(event) => setNotifications({ ...notifications, avisarSaldoProjetadoNegativo: event.target.checked })} /> Saldo projetado negativo</label><Button onClick={() => void saveNotifications()}>Salvar notificações</Button></Card>}</div></>; }

function DashboardBudgetCard({ budget, onOpen }: { budget: { totalPlanejadoCentavos: number; totalRealizadoCentavos: number; saldoDisponivelCentavos: number; percentualUtilizado: number; topCategorias: BudgetLine[] }; onOpen: () => void }) { return <Card title="Orçamento do mês"><div className="metric-grid compact budget-dashboard-metrics"><Metric title="Planejado" value={money(budget.totalPlanejadoCentavos)} tone="balance" /><Metric title="Realizado" value={money(budget.totalRealizadoCentavos)} tone="expense" /><Metric title="Disponível" value={money(budget.saldoDisponivelCentavos)} tone={budget.saldoDisponivelCentavos < 0 ? 'expense' : 'income'} /></div><div className="budget-progress"><div><span>Uso do orçamento</span><strong>{budget.percentualUtilizado.toLocaleString('pt-BR')}%</strong></div><i style={{ width: `${Math.min(100, Math.max(2, budget.percentualUtilizado))}%` }} /></div><div className="budget-top-list">{budget.topCategorias.slice(0, 3).map((item) => <span key={`${item.categoriaId}-${item.membroId}`}><b>{item.categoriaNome}</b><small>{item.percentualUtilizado.toLocaleString('pt-BR')}% · {money(item.realizadoCentavos)}</small></span>)}</div><Button tone="secondary" onClick={onOpen}>Abrir orçamento mensal</Button></Card>; }

function PlanningPage({ route, notify }: { route: Route; notify: (message: string, kind?: ToastKind) => void }) {
  const now = new Date(); const [year, setYear] = useState(now.getFullYear()); const [month, setMonth] = useState(now.getMonth() + 1); const [memberId, setMemberId] = useState(''); const [members, setMembers] = useState<Member[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [budgets, setBudgets] = useState<Budget[]>([]); const [selectedId, setSelectedId] = useState(''); const [summary, setSummary] = useState<BudgetSummary | null>(null); const [comparison, setComparison] = useState<BudgetComparison | null>(null); const [busy, setBusy] = useState(true); const [addingItem, setAddingItem] = useState(false); const [showBudgetModal, setShowBudgetModal] = useState(false); const [budgetToEdit, setBudgetToEdit] = useState<Budget | null>(null); const isComparison = route === 'planning/actual-vs-planned';
  const load = async () => { setBusy(true); try { const [people, categoryList, list] = await Promise.all([api.members(), api.categories(), api.budgets(route === 'planning' ? { membroId: memberId || undefined } : { ano: year, mes: month, membroId: memberId || undefined })]); setMembers(people.filter((item) => item.ativo)); setCategories(categoryList.filter((item) => item.ativo && item.tipo === 'Despesa')); setBudgets(list); const next = list.find((item) => item.id === selectedId) ?? list[0]; setSelectedId(next?.id ?? ''); if (next) { const [nextSummary, nextComparison] = await Promise.all([api.budgetSummary(next.id), api.budgetComparison(next.id)]); setSummary(nextSummary); setComparison(nextComparison); } else { setSummary(null); setComparison(null); } } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível carregar o planejamento.', 'error'); } finally { setBusy(false); } };
  useEffect(() => { void load(); }, [year, month, memberId, route]);
  const reloadSummary = async (id = selectedId) => { if (!id) return; const [nextSummary, nextComparison] = await Promise.all([api.budgetSummary(id), api.budgetComparison(id)]); setSummary(nextSummary); setComparison(nextComparison); };
  const saveBudget = async (payload: BudgetRequest) => { try { const saved = budgetToEdit ? await api.updateBudget(budgetToEdit.id, payload) : await api.createBudget(payload); setShowBudgetModal(false); setBudgetToEdit(null); setSelectedId(saved.id); notify(budgetToEdit ? 'Orçamento atualizado.' : 'Orçamento criado localmente.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao salvar orçamento.', 'error'); } };
  const addItem = async (payload: BudgetItemRequest) => { if (!selectedId) return; try { await api.addBudgetItem(selectedId, payload); setAddingItem(false); notify('Limite de categoria adicionado.'); await reloadSummary(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao adicionar item.', 'error'); } };
  const statusAction = async (action: 'activate' | 'close' | 'reopen') => { if (!selectedId) return; try { if (action === 'activate') await api.activateBudget(selectedId); if (action === 'close') await api.closeBudget(selectedId); if (action === 'reopen') await api.reopenBudget(selectedId); notify(action === 'close' ? 'Orçamento encerrado e preservado no histórico.' : 'Status do orçamento atualizado.'); await load(); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível alterar o status.', 'error'); } };
  const copy = async () => { if (!selectedId) return; const target = window.prompt('Mês de destino (AAAA-MM):', `${year}-${String(month === 12 ? 1 : month + 1).padStart(2, '0')}`); if (!target || !/^\d{4}-\d{2}$/.test(target)) return; const [targetYear, targetMonth] = target.split('-').map(Number); const adjustment = window.prompt('Reajuste percentual opcional:', '0'); try { await api.copyBudget(selectedId, { ano: targetYear, mes: targetMonth, membroId: memberId || undefined, reajustePercentual: Number(adjustment?.replace(',', '.') ?? 0) || 0 }); notify('Orçamento copiado para o novo mês.'); setYear(targetYear); setMonth(targetMonth); } catch (error) { notify(error instanceof Error ? error.message : 'Não foi possível copiar o orçamento.', 'error'); } };
  const currentBudget = summary?.orcamento ?? budgets.find((item) => item.id === selectedId); const lines = isComparison ? comparison?.linhas ?? [] : summary?.linhas ?? [];
  if (busy && budgets.length === 0) return <p>Carregando planejamento financeiro…</p>;
  return <><PageIntro title={isComparison ? 'Compare o que foi previsto com o gasto real e identifique desvios.' : route === 'planning' ? 'Planeje o mês, acompanhe limites e tome decisões antes do estouro.' : 'Defina limites por categoria e acompanhe o consumo em tempo real.'} action={<div className="page-actions"><Button onClick={() => setShowBudgetModal(true)}>Novo orçamento</Button>{currentBudget && <Button tone="secondary" onClick={() => void copy()}>Copiar para outro mês</Button>}</div>} /><div className="budget-filters"><label>Ano<input type="number" min="2000" max="2200" value={year} onChange={(event) => setYear(Number(event.target.value))} /></label><label>Mês<select value={month} onChange={(event) => setMonth(Number(event.target.value))}>{Array.from({ length: 12 }, (_, index) => <option key={index + 1} value={index + 1}>{new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date(2020, index, 1))}</option>)}</select></label><label>Membro<select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Todos / família</option>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></label><label>Orçamento<select value={selectedId} onChange={async (event) => { setSelectedId(event.target.value); if (event.target.value) await reloadSummary(event.target.value); }}><option value="">Selecione um orçamento</option>{budgets.map((item) => <option key={item.id} value={item.id}>{item.descricao} · {budgetStatus(item.status)}</option>)}</select></label></div>{route === 'planning' && <Card title="Histórico do período"><BudgetHistory budgets={budgets} onOpen={(id) => { setSelectedId(id); void reloadSummary(id); }} /></Card>}{currentBudget && summary ? <><div className="metric-grid"><Metric title="Receita prevista" value={money(currentBudget.receitaPrevistaCentavos)} tone="income" /><Metric title="Total planejado" value={money(summary.totalPlanejadoCentavos)} tone="balance" /><Metric title="Realizado" value={money(summary.totalRealizadoCentavos)} tone="expense" /><Metric title={isComparison ? 'Variação' : 'Disponível'} value={money(isComparison ? comparison?.variacaoCentavos ?? 0 : summary.saldoOrcamentarioCentavos)} tone={isComparison ? ((comparison?.variacaoCentavos ?? 0) > 0 ? 'expense' : 'income') : (summary.saldoOrcamentarioCentavos < 0 ? 'expense' : 'income')} /></div><div className="metric-grid compact"><Metric title="Uso" value={`${(isComparison ? comparison?.totalPlanejadoCentavos ? (comparison.totalRealizadoCentavos * 100 / comparison.totalPlanejadoCentavos).toFixed(2) : 0 : summary.percentualUtilizado).toLocaleString('pt-BR')}%`} tone="expense" /><Metric title="Projeção" value={money(summary.totalProjetadoCentavos)} tone="expense" /><Metric title="Poupança planejada" value={`${summary.poupancaPlanejadaPercentual.toLocaleString('pt-BR')}%`} tone="income" /></div><Card title={isComparison ? 'Previsto x realizado por categoria' : 'Execução do orçamento'}><div className="budget-toolbar"><span className={`status ${currentBudget.status.toLowerCase()}`}>{budgetStatus(currentBudget.status)}</span><span className="form-hint">Variação positiva significa gasto acima do planejado.</span><div className="page-actions">{!isComparison && currentBudget.status !== 'ENCERRADO' && <Button onClick={() => setAddingItem(true)}>Adicionar categoria</Button>}{currentBudget.status === 'RASCUNHO' && <Button tone="secondary" onClick={() => void statusAction('activate')}>Ativar</Button>}{currentBudget.status === 'ATIVO' && <Button tone="secondary" onClick={() => void statusAction('close')}>Encerrar mês</Button>}{currentBudget.status === 'ENCERRADO' && <Button tone="secondary" onClick={() => void statusAction('reopen')}>Reabrir</Button>}</div></div><BudgetTable lines={lines} onDelete={async (item) => { if (!selectedId || !item.itemId || !window.confirm(`Remover o limite de ${item.categoriaNome}?`)) return; try { await api.deleteBudgetItem(selectedId, item.itemId); notify('Item removido; o histórico foi preservado.'); await reloadSummary(); } catch (error) { notify(error instanceof Error ? error.message : 'Erro ao remover item.', 'error'); } }} /></Card></> : <Card title="Comece pelo orçamento do mês"><p>Crie um orçamento, informe a receita esperada e adicione limites por categoria. O realizado será calculado automaticamente a partir das movimentações e compras no cartão.</p><Button onClick={() => setShowBudgetModal(true)}>Criar orçamento de {String(month).padStart(2, '0')}/{year}</Button></Card>}{showBudgetModal && <BudgetModal onClose={() => setShowBudgetModal(false)} onSave={saveBudget} members={members} />}{addingItem && selectedId && <BudgetItemModal onClose={() => setAddingItem(false)} onSave={addItem} members={members} categories={categories} />}</>;
}
function BudgetHistory({ budgets, onOpen }: { budgets: Budget[]; onOpen: (id: string) => void }) { return budgets.length === 0 ? <EmptyState text="Nenhum orçamento encontrado para este mês." /> : <div className="table-scroll"><table><thead><tr><th>Período</th><th>Descrição</th><th>Membro</th><th>Receita prevista</th><th>Status</th><th /></tr></thead><tbody>{budgets.map((item) => <tr key={item.id}><td>{String(item.mes).padStart(2, '0')}/{item.ano}</td><td><strong>{item.descricao}</strong><small>Atualizado em {date(item.atualizadoEm)}</small></td><td>{item.membroNome ?? 'Família'}</td><td>{money(item.receitaPrevistaCentavos)}</td><td><span className={`status ${item.status.toLowerCase()}`}>{budgetStatus(item.status)}</span></td><td className="actions"><button onClick={() => onOpen(item.id)}>Abrir</button></td></tr>)}</tbody></table></div>; }
function BudgetTable({ lines, onDelete }: { lines: BudgetLine[]; onDelete: (item: BudgetLine) => Promise<void> }) { return lines.length === 0 ? <EmptyState text="Adicione categorias para começar o acompanhamento." /> : <div className="table-scroll"><table><thead><tr><th>Categoria / membro</th><th>Planejado</th><th>Realizado</th><th>Disponível</th><th>Uso</th><th>Variação</th><th>Projetado</th><th /></tr></thead><tbody>{lines.map((item) => <tr key={`${item.itemId ?? item.categoriaId}-${item.membroId ?? 'shared'}`}><td><strong>{item.categoriaNome}</strong><small>{item.membroNome ?? 'Família / compartilhado'}{item.semOrcamento ? ' · sem limite definido' : ''}</small></td><td>{item.semOrcamento ? '—' : money(item.valorPlanejadoCentavos)}</td><td className="expense-text">{money(item.realizadoCentavos)}</td><td className={item.disponivelCentavos < 0 ? 'expense-text' : 'income-text'}>{item.semOrcamento ? '—' : money(item.disponivelCentavos)}</td><td><span className={`budget-pill ${item.situacao.toLowerCase()}`}>{item.percentualUtilizado.toLocaleString('pt-BR')}%</span></td><td className={item.variacaoCentavos > 0 ? 'expense-text' : 'income-text'}>{item.semOrcamento ? '—' : `${item.variacaoCentavos > 0 ? '+' : ''}${money(item.variacaoCentavos)}`}</td><td>{item.semOrcamento ? '—' : money(item.projetadoCentavos)}</td><td className="actions">{item.itemId && <button onClick={() => void onDelete(item)}>Remover</button>}</td></tr>)}</tbody></table></div>; }
function BudgetModal({ members, onClose, onSave }: { budget?: Budget; members: Member[]; onClose: () => void; onSave: (payload: BudgetRequest) => Promise<void> }) { const now = new Date(); const [year, setYear] = useState(now.getFullYear()); const [month, setMonth] = useState(now.getMonth() + 1); const [memberId, setMemberId] = useState(''); const [description, setDescription] = useState(`Orçamento ${String(month).padStart(2, '0')}/${year}`); const [revenue, setRevenue] = useState('0'); const [observation, setObservation] = useState(''); const [busy, setBusy] = useState(false); return <Modal title="Novo orçamento mensal" onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ ano: year, mes: month, membroId: memberId || undefined, descricao: description, receitaPrevistaCentavos: Math.round(Number(revenue.replace(',', '.')) * 100), modoReceitaPrevista: 'MANUAL', status: 'RASCUNHO', observacao: observation || undefined }); setBusy(false); }}><div className="form-grid"><Field label="Ano"><input type="number" value={year} onChange={(event) => setYear(Number(event.target.value))} min="2000" max="2200" /></Field><Field label="Mês"><input type="number" value={month} onChange={(event) => setMonth(Number(event.target.value))} min="1" max="12" /></Field><Field label="Membro / escopo"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Família / consolidado</option>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Descrição"><input value={description} onChange={(event) => setDescription(event.target.value)} autoFocus /></Field><Field label="Receita prevista (R$)"><input type="number" min="0" step="0.01" value={revenue} onChange={(event) => setRevenue(event.target.value)} /></Field></div><Field label="Observação"><textarea rows={2} value={observation} onChange={(event) => setObservation(event.target.value)} /></Field><p className="form-hint">A receita é manual nesta sprint. O total planejado será a soma dos itens de despesa.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || !description.trim()}>{busy ? 'Salvando…' : 'Salvar orçamento'}</Button></div></Form></Modal>; }
function BudgetItemModal({ members, categories, onClose, onSave }: { members: Member[]; categories: Category[]; onClose: () => void; onSave: (payload: BudgetItemRequest) => Promise<void> }) { const [categoryId, setCategoryId] = useState(categories[0]?.id ?? ''); const [memberId, setMemberId] = useState(''); const [value, setValue] = useState(''); const [busy, setBusy] = useState(false); return <Modal title="Adicionar limite por categoria" onClose={onClose}><Form onSubmit={async (event) => { event.preventDefault(); setBusy(true); await onSave({ categoriaId: categoryId, membroId: memberId || undefined, valorPlanejadoCentavos: Math.round(Number(value.replace(',', '.')) * 100) }); setBusy(false); }}><Field label="Categoria"><select value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>{categories.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Membro / escopo"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Família / compartilhado</option>{members.map((item) => <option key={item.id} value={item.id}>{item.nome}</option>)}</select></Field><Field label="Valor planejado (R$)"><input type="number" min="0.01" step="0.01" value={value} onChange={(event) => setValue(event.target.value)} autoFocus /></Field><p className="form-hint">Para evitar dupla contagem, um ramo pode ser orçado no pai ou nas filhas, nunca nos dois níveis.</p><div className="modal-actions"><Button tone="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy || !categoryId || !value}>{busy ? 'Adicionando…' : 'Adicionar limite'}</Button></div></Form></Modal>; }
function budgetStatus(status: BudgetStatus) { return status === 'RASCUNHO' ? 'Rascunho' : status === 'ATIVO' ? 'Ativo' : 'Encerrado'; }
function PageIntro({ title, action }: { title: string; action?: ReactNode }) { return <div className="page-intro"><p>{title}</p>{action}</div>; }
function Status({ active }: { active: boolean }) { return <span className={`status ${active ? 'active' : 'inactive'}`}>{active ? 'Ativo' : 'Inativo'}</span>; }

export default App;
